/* Formula 1 — L0 Basi: capire la F1 da zero. 9 lezioni per principianti assoluti.
   Regolamento descritto: quello in vigore nelle stagioni recenti (fino al 2025); le regole cambiano ogni anno. */
(function (ST) {
  'use strict';
  const C = ST.content, { mc, fill, order } = C;

  /* ---------- 1 · Che cos'è la F1 ---------- */
  C.addTopic({
    id: 'f1-che-cose-la-f1', subject: 'f1', stage: 'L0', minutes: 12,
    title: 'Che cos’è la Formula 1',
    summary: 'Il campionato mondiale di monoposto: chi lo organizza (FIA e promotore), come si distingue dalle altre corse e che differenza c’è tra titolo piloti e titolo costruttori.',
    objectives: ['Spiegare che cos’è la F1 e chi la governa (FIA e promotore)', 'Distinguere le monoposto dalle altre categorie di corse', 'Distinguere campionato piloti e campionato costruttori'],
    pages: [
      { h: 'Una gara di auto, in un campionato mondiale', b: `La **Formula 1** (F1) è la massima categoria delle corse in pista con **monoposto**, cioè auto da corsa con un solo posto, quello del pilota, e con le ruote scoperte (fuori dalla carrozzeria).\n\nSi chiama **campionato del mondo** perché è formato da una serie di gare, chiamate **Gran Premi**, che si svolgono in Paesi diversi, in tutto il mondo, nell’arco di una stagione (di solito da marzo a dicembre). Ogni Gran Premio assegna dei **punti**; a fine stagione chi ha più punti vince il titolo.\n\nIl primo campionato mondiale di F1 si è disputato nel **1950**.\n\nLa parola «**formula**» indica un insieme di regole che tutti i concorrenti devono rispettare: peso minimo, dimensioni, motore, sicurezza. Se le regole sono uguali per tutti, vince chi le sfrutta meglio.\n\n> In una frase: la F1 è un campionato mondiale di gare tra monoposto costruite secondo regole comuni.` },
      { h: 'La FIA: chi scrive le regole', b: `La **FIA** (Fédération Internationale de l’Automobile, «Federazione Internazionale dell’Automobile») è l’ente mondiale dello sport automobilistico. È stata fondata nel **1904** ed ha sede a Parigi.\n\nLa FIA è l’**autorità sportiva** della F1. Questo significa che:\n\n- scrive il **regolamento sportivo** (come si svolge un weekend, come si danno i punti) e il **regolamento tecnico** (come devono essere fatte le auto);\n- nomina i **commissari** (in inglese *stewards*), cioè i giudici che applicano le regole e danno le penalità;\n- si occupa della **sicurezza** di piste e vetture;\n- assegna ufficialmente i titoli a fine anno.\n\nPensa a un arbitro e a un libro delle regole: la FIA è l’arbitro e chi scrive il libro. Le regole cambiano nel tempo: in questo corso descriviamo il **regolamento in vigore nelle stagioni recenti**, e ti avvisiamo quando un aspetto è in evoluzione.` },
      { h: 'Il promotore: chi organizza lo spettacolo', b: `Una cosa è fare le regole, un’altra è **organizzare e vendere lo spettacolo**. Il secondo compito spetta al **promotore commerciale** del campionato, la società **Formula One Group** (il marchio è «Formula 1»), che dal 2017 appartiene all’azienda americana **Liberty Media**.\n\nIl promotore:\n\n- firma i contratti con i circuiti e i Paesi che ospitano i Gran Premi;\n- vende i **diritti televisivi** a televisioni e piattaforme di streaming;\n- si occupa di sponsor del campionato, biglietti e immagine;\n- distribuisce una parte degli incassi alle squadre.\n\nQuindi i ruoli sono tre: la **FIA** fa le regole e le fa rispettare; il **promotore** commercializza il campionato; le **squadre** costruiscono le auto e gareggiano.\n\n> Attenzione: «promotore» non significa «proprietario delle auto». Le auto sono delle squadre.` },
      { h: 'Monoposto e altre corse: le differenze', b: `Non tutte le corse sono F1. Ecco le principali categorie, con la caratteristica che le distingue.\n\n- **Formula 1**: monoposto, ruote scoperte, il vertice per velocità e tecnologia.\n- **Formula 2 e Formula 3**: anch’esse monoposto, ma più semplici e identiche per tutti. Sono categorie di **formazione** dove i giovani piloti si preparano alla F1.\n- **IndyCar**: monoposto americane, spesso su circuiti ovali.\n- **Formula E**: monoposto **elettriche**, spesso su circuiti cittadini.\n- **Gare di durata** (come la 24 Ore di Le Mans): auto chiuse, con più piloti che si danno il cambio per molte ore.\n- **Rally**: auto derivate da quelle stradali, su strade sterrate o asfaltate, contro il tempo.\n- **NASCAR**: grosse auto «stock» con carrozzeria chiusa, soprattutto su ovali americani.\n- **MotoGP**: moto, non auto.\n\nLa F1 è unica perché costruttori e squadre progettano **auto create apposta per la gara**: nessuna è in vendita, nessuna deriva da un modello stradale.` },
      { h: 'La piramide delle categorie', b: `Per arrivare in F1 un pilota percorre di solito una **scala di categorie**, partendo da molto giovane.\n\n1. **Kart**: si comincia di solito da bambini. Insegna traiettorie e sorpassi.\n2. **Formula 4**: prime monoposto, per adolescenti.\n3. **Formula 3** e **Formula 2**: monoposto veloci, con gare nei weekend della F1.\n4. **Formula 1**: il vertice, con un numero molto limitato di posti.\n\nIn ogni categoria bisogna ottenere risultati e accumulare punti per ottenere la **superlicenza**, il documento della FIA indispensabile per correre in F1.\n\nIn una stagione corrono in F1 solo **venti piloti** circa (nelle stagioni recenti): è uno dei lavori più selettivi che esistano. Da qui il valore di esserci: i piloti sono pochissimi rispetto a tutte le persone che gareggiano nel mondo.` },
      { h: 'Il campionato piloti', b: `Il **campionato piloti** (in inglese *Drivers’ Championship*) assegna il titolo di **campione del mondo** al pilota che, alla fine della stagione, ha **più punti**.\n\nOgni pilota guadagna punti con il proprio piazzamento nelle gare. Contano solo i suoi risultati personali: se cambia squadra a metà anno, i punti già ottenuti restano suoi.\n\nIn caso di **parità di punti** si guarda chi ha ottenuto più vittorie; se ancora pari, più secondi posti, e così via.\n\n> Esempio: il pilota A vince 3 Gran Premi e il pilota B ne vince 2 ma arriva spesso secondo. Alla fine conta il totale dei punti, non il numero di vittorie: B può anche vincere il titolo se è più regolare.\n\nIl titolo piloti è quello più famoso, quello che si racconta dicendo «X è campione del mondo».` },
      { h: 'Il campionato costruttori', b: `Esiste anche un secondo titolo: il **campionato costruttori** (*Constructors’ Championship*), che premia la **squadra**.\n\nI punti di una squadra sono la **somma dei punti dei suoi due piloti**. Se un pilota ottiene 25 punti e il compagno 18, la squadra ne guadagna 43 in quel Gran Premio.\n\nIl titolo costruttori è importante perché:\n\n- indica quale squadra ha costruito l’auto migliore nel complesso, e non soltanto il pilota più forte;\n- determina una parte rilevante dei **premi in denaro** che la squadra riceve dal promotore, in base alla classifica finale.\n\nLe due classifiche possono avere esiti diversi: un pilota molto bravo in una squadra debole può vincere gare ma restare indietro nei costruttori, mentre una squadra con due piloti costanti può vincere il titolo costruttori senza avere il campione piloti.\n\nIn breve: **piloti = persone, costruttori = squadre**.` },
      { h: 'Quanti sono, in sintesi', b: `Riassumiamo i numeri, validi per le stagioni recenti.\n\n- Squadre: **10**, con **2 piloti** ciascuna, quindi **20 auto** in pista. Dal **2026** è prevista l’entrata di una squadra in più (con un conseguente aumento delle auto): è un esempio di come il regolamento cambi.\n- Gran Premi per stagione: fino a **24**.\n- Due titoli: **piloti** e **costruttori**.\n\n> Calcolo: 10 squadre × 2 piloti = 20 auto.\n\nIn pratica un tifoso segue due storie in parallelo: la lotta tra i **piloti** per il titolo individuale e quella tra le **squadre** per il titolo costruttori.\n\nNel resto del corso vedremo come è fatto un weekend di gara, chi lavora in una squadra, come si assegnano i punti e come capire una gara dal divano.` }
    ],
    exercises: [
      mc('Che cosa significa «monoposto»?', ['Auto da corsa con un solo posto, quello del pilota', 'Auto con un solo motore', 'Auto che corre una sola gara', 'Auto con una sola ruota di scorta'], 0, 'Mono = uno: c’è un solo posto, per il pilota.'),
      mc('Chi scrive il regolamento della F1 e nomina i commissari?', ['La FIA', 'Il promotore commerciale', 'Le televisioni', 'Gli sponsor'], 0, 'La FIA è l’autorità sportiva: regole, controlli e commissari.'),
      mc('Che cosa fa il promotore commerciale della F1?', ['Organizza e vende il campionato, ad esempio i diritti TV', 'Costruisce le auto', 'Guida le auto in gara', 'Decide le penalità'], 0, 'Il promotore commercializza lo spettacolo, firma i contratti con i circuiti e vende i diritti TV.'),
      mc('Quale categoria NON è una gara di monoposto?', ['Rally', 'Formula 2', 'Formula E', 'IndyCar'], 0, 'I rally si corrono con auto derivate da quelle stradali, non monoposto.'),
      mc('A che cosa serve la Formula 2?', ['A formare piloti giovani in vista della F1', 'A fare prove per i motori della F1', 'A sostituire un Gran Premio', 'A premiare le squadre costruttrici'], 0, 'È una categoria di formazione sulla strada verso la F1.'),
      fill('Un pilota ottiene 25 punti e il suo compagno di squadra 18. Quanti punti guadagna la squadra nel campionato costruttori?', ['43'], '25 + 18 = 43.'),
      fill('Nelle stagioni recenti ci sono 10 squadre con 2 piloti ciascuna. Quante auto sono in pista?', ['20'], '10 × 2 = 20.'),
      mc('Chi vince il campionato piloti?', ['Chi ha più punti a fine stagione', 'Chi vince più gare, sempre', 'Chi guida l’auto più veloce', 'La squadra con più piloti'], 0, 'Conta il totale dei punti; a parità si guardano le vittorie.'),
      mc('Perché il campionato costruttori è importante per la squadra?', ['Misura la squadra nel suo complesso e determina premi in denaro', 'Assegna il titolo al pilota', 'Serve solo a decidere i circuiti', 'Non conta nulla'], 0, 'La somma dei punti dei due piloti misura la squadra e incide sui premi.'),
      mc('Qual è il documento della FIA indispensabile per correre in F1?', ['La superlicenza', 'La patente stradale', 'Il passaporto sportivo del promotore', 'Il contratto TV'], 0, 'Si ottiene con risultati e punti nelle categorie giovanili.'),
      order('Ordina la scala di categorie, dalla più giovane alla F1', ['Kart', 'Formula 4', 'Formula 3', 'Formula 2', 'Formula 1'], 'Questo è il percorso tipico, anche se non è l’unico.')
    ],
    test: [
      mc('In che anno si è disputato il primo campionato mondiale di F1?', ['1950', '1904', '1975', '2000'], 0, 'Il primo mondiale è del 1950 (la FIA invece è del 1904).'),
      mc('Chi è proprietario delle auto che gareggiano in F1?', ['Le squadre', 'La FIA', 'Il promotore', 'I circuiti'], 0, 'Le auto sono progettate e possedute dalle squadre.'),
      fill('Una squadra ha due piloti che finiscono con 12 e 8 punti. Quanti punti prende la squadra?', ['20'], '12 + 8 = 20.'),
      mc('Che cosa significa «formula» in Formula 1?', ['Un insieme di regole uguali per tutti', 'Una ricetta del carburante', 'Il nome del primo circuito', 'Una formula matematica per i punti'], 0, 'Indica le regole a cui tutti i concorrenti devono attenersi.'),
      mc('Quale titolo premia anche la qualità dell’auto nel suo insieme?', ['Costruttori', 'Piloti', 'Nessuno dei due', 'Il titolo del promotore'], 0, 'La somma dei punti dei due piloti misura la squadra intera.'),
      mc('Che cosa distingue la Formula E dalla F1?', ['Le monoposto sono elettriche', 'Non ha piloti', 'È una gara di moto', 'Si corre solo di giorno'], 0, 'La E sta per elettrica.'),
      mc('Se un pilota cambia squadra a metà stagione, che fine fanno i punti già ottenuti?', ['Restano suoi nel campionato piloti', 'Si azzerano', 'Passano alla vecchia squadra come punti piloti', 'Si dividono in due'], 0, 'Nel campionato piloti i punti sono personali.')
    ]
  });

  /* ---------- 2 · Il weekend di gara ---------- */
  C.addTopic({
    id: 'f1-il-weekend-di-gara', subject: 'f1', stage: 'L0', minutes: 12,
    title: 'Il weekend di gara',
    summary: 'Prove libere, qualifiche, gara e formato sprint: che cosa succede da venerdì a domenica, quanto dura una gara e dove si corre.',
    objectives: ['Elencare le sessioni di un weekend standard e di uno sprint', 'Ricordare durata massima e distanza minima di una gara', 'Capire come è organizzato il calendario e in quali Paesi si corre'],
    prereq: ['f1-che-cose-la-f1'],
    pages: [
      { h: 'Un Gran Premio dura tre giorni', b: `Un **Gran Premio** non è soltanto la gara della domenica: è un **weekend** di tre giorni, dal venerdì alla domenica, su uno stesso circuito.\n\nSchema di un weekend **standard** (nelle stagioni recenti):\n\n- **Venerdì**: prove libere 1 e 2.\n- **Sabato**: prove libere 3 e qualifiche.\n- **Domenica**: la gara.\n\nPerché tre giorni? Le squadre arrivano su una pista che spesso non conoscono bene o su cui hanno poche informazioni, hanno bisogno di **provare** le auto, scegliere le regolazioni e solo alla fine **gareggiare**.\n\nGli orari sono sempre **locali**: se la gara è alle 15:00 del Paese ospitante, in Italia l’ora può essere diversa a causa del fuso orario.` },
      { h: 'Le prove libere', b: `Le **prove libere** (in inglese *Free Practice*, abbreviate FP1, FP2, FP3) sono sessioni di **allenamento**: non assegnano punti né posizioni di partenza.\n\nDurano **60 minuti** ciascuna. Servono a:\n\n- trovare l’**assetto** dell’auto, cioè le regolazioni (altezza da terra, inclinazione delle ali, durezza delle sospensioni…);\n- provare le **gomme** e capire quanto durano;\n- far prendere confidenza ai piloti con la pista;\n- simulare un giro di qualifica e un tratto di gara.\n\n> Nei tempi delle prove libere non bisogna leggere troppo: molte auto girano con poca benzina o con gomme diverse, e nascondono la loro vera velocità.\n\nIl nome «libere» indica che non c’è una classifica ufficiale che conti: ciascuna squadra decide il proprio programma di lavoro.` },
      { h: 'Le qualifiche', b: `Le **qualifiche** decidono l’**ordine di partenza** in gara (la **griglia**). Si svolgono il sabato e sono divise in tre parti a eliminazione.\n\n- **Q1**: **18 minuti**, partecipano tutte le 20 auto. Le 5 più lente sono eliminate e partiranno dalla 16ª posizione in poi.\n- **Q2**: **15 minuti**, con 15 auto. Le 5 più lente sono eliminate e partono dall’11ª alla 15ª.\n- **Q3**: **12 minuti**, con le 10 migliori, che si giocano le prime 10 posizioni della griglia.\n\n> Calcolo: 20 − 5 = 15 auto in Q2; 15 − 5 = 10 auto in Q3. Durata totale: 18 + 15 + 12 = **45 minuti**.\n\nChi fa il giro più veloce in Q3 conquista la **pole position**, cioè parte primo. In ogni parte, il pilota sceglie in che momento uscire: conta il **tempo di un singolo giro** il più veloce possibile.` },
      { h: 'La gara', b: `La **gara** si disputa la domenica. Le regole base:\n\n- Si parte da fermi, con una **partenza da fermo** guidata da cinque luci rosse sopra la pista: quando si spengono tutte, la gara è partita.\n- La distanza è definita in **giri**: si prende il numero di giri che supera i **305 km** (un’eccezione è il circuito di Monaco, con circa 260 km).\n- C’è un **limite di tempo**: la gara non può durare più di **2 ore**, interruzioni escluse. Se si ferma per bandiera rossa, il tempo totale massimo è 3 ore.\n- Vince chi taglia per primo il traguardo, dopo il numero di giri previsto; gli altri sono classificati in base ai giri e all’ordine di arrivo.\n\nLa distanza è fissata in modo che una gara duri tipicamente **un’ora e mezza** circa.\n\n> Esempio: a 200 km/h di media, 305 km richiedono 305 / 200 = 1,525 ore, cioè circa 91 minuti e mezzo.` },
      { h: 'Il formato sprint', b: `In alcuni weekend (nelle stagioni recenti circa **sei** all’anno) si usa il formato **sprint**, che aggiunge una **gara breve** il sabato.\n\nOrdine tipico dei weekend sprint (formato in vigore dal 2024):\n\n- **Venerdì**: una sola sessione di prove libere (60 minuti), poi le **qualifiche sprint** (*Sprint Qualifying*), che decidono la griglia della gara breve.\n- **Sabato**: la **gara sprint**, poi le **qualifiche** normali per la gara della domenica.\n- **Domenica**: la **gara** principale.\n\nLa **gara sprint** è lunga circa **100 km** (circa un terzo di un Gran Premio, una mezz’ora scarsa) e non prevede una sosta obbligatoria. Assegna punti ai primi **otto** classificati.\n\nIl formato sprint dà ai tifosi più azione e meno tempo per le prove, con più rischi per le squadre: hanno una sola sessione di prove libere per mettere a punto l’auto.` },
      { h: 'Orari, fusi e durata', b: `Gli **orari** dipendono dal Paese: ogni circuito ha il proprio **fuso orario**, quindi la stessa gara può cadere alle 15:00 locali (le 15:00 a Monza coincidono con l’ora italiana) ma di notte in Italia se si corre in Asia o in America.\n\nAlcune gare si corrono **di sera** con i fari (circuiti come Singapore, Bahrein, Abu Dhabi, Las Vegas); altre, nei Paesi con poca luce, partono nel primo pomeriggio.\n\nDurata tipica:\n\n- gara: circa **1 ora e 30 minuti** (massimo 2 ore, senza interruzioni);\n- sprint: circa **30 minuti**;\n- qualifiche: 45 minuti di pista (18 + 15 + 12), a cui si aggiungono le pause tra una parte e l’altra;\n- prove libere: 60 minuti.\n\n> Domanda utile: a che ora inizia la gara **qui da noi**? Guarda sempre l’orario convertito dal fuso: il calendario ufficiale indica l’ora locale, ed è facile sbagliarsi.` },
      { h: 'Il calendario e i Paesi', b: `Il **calendario** della stagione ha fino a **24 Gran Premi** (nelle stagioni recenti), da **marzo** a **dicembre**, su circuiti in **Europa, Asia, Medio Oriente, Nord e Sud America, Oceania**.\n\nEsempi di tappe tradizionali:\n\n- **Italia**: Monza (Gran Premio d’Italia);\n- **Principato di Monaco**: il circuito cittadino più celebre;\n- **Regno Unito**: Silverstone;\n- **Belgio**: Spa-Francorchamps;\n- **Giappone**: Suzuka;\n- **Australia**: Melbourne;\n- **Brasile**: Interlagos;\n- **Singapore**: Marina Bay;\n- **Emirati Arabi**: Abu Dhabi.\n\nLa scelta delle tappe cambia da anno ad anno: alcuni circuiti escono dal calendario, altri entrano. Controlla sempre il calendario ufficiale della stagione.\n\nLe squadre viaggiano in tutto il mondo e trasportano auto, ricambi e materiale: per i Gran Premi lontani spedizioni via mare o via aerea, con regole sui costi.` },
      { h: 'Riepilogo del weekend', b: `Ricapitoliamo il weekend **standard**:\n\n- **Venerdì**: FP1 e FP2, ciascuna di 60 minuti. Si prova.\n- **Sabato**: FP3 (60 min) e qualifiche (Q1 18 min, Q2 15 min, Q3 12 min). Si decide la griglia.\n- **Domenica**: gara, circa 305 km, massimo 2 ore.\n\nE il weekend **sprint**:\n\n- **Venerdì**: FP1 e qualifiche sprint.\n- **Sabato**: gara sprint (circa 100 km) e qualifiche.\n- **Domenica**: gara.\n\n> Calcolo utile: se in un weekend standard sommi le sessioni (60 + 60 + 60 + 45 minuti di pista) e aggiungi la gara, in pista passano circa 225 minuti di prove e qualifiche, più una gara di circa 90 minuti.\n\nDurate e formati sono quelli in vigore nelle stagioni recenti; possono cambiare per decisione della FIA.` }
    ],
    exercises: [
      mc('Quale sessione di un weekend standard decide l’ordine di partenza della gara?', ['Le qualifiche', 'Le prove libere 1', 'La gara sprint, sempre', 'Il giro di ricognizione'], 0, 'La griglia nasce dalle qualifiche (nei weekend sprint c’è anche una griglia per la gara breve).'),
      fill('Quanti minuti dura una sessione di prove libere?', ['60'], 'Nel regolamento recente, 60 minuti.'),
      fill('Alla fine di Q1, quante auto sono eliminate?', ['5'], 'Le 5 più lente, che partono dal 16º posto in poi.'),
      fill('Quante auto partecipano a Q3?', ['10'], '20 − 5 = 15 in Q2; 15 − 5 = 10 in Q3.'),
      fill('Quanto durano in totale Q1 + Q2 + Q3, in minuti? (18 + 15 + 12)', ['45'], '18 + 15 + 12 = 45.'),
      mc('Chi conquista la pole position?', ['Chi fa il giro più veloce in Q3', 'Chi vince le prove libere', 'Chi vince la gara sprint', 'Chi ha più punti in classifica'], 0, 'La pole è il primo posto in griglia, e va al miglior tempo delle qualifiche.'),
      mc('Qual è la distanza minima di una gara (escluse eccezioni come Monaco)?', ['305 km', '100 km', '500 km', '200 km'], 0, 'Si prende il numero di giri che supera i 305 km.'),
      mc('Quanto può durare al massimo una gara senza interruzioni?', ['2 ore', '1 ora', '3 ore e 30', '45 minuti'], 0, 'Limite di 2 ore (3 ore in totale se c’è una bandiera rossa).'),
      fill('A una media di 200 km/h, quanti minuti servono per 305 km? (arrotonda al minuto più vicino)', ['92', '91'], '305 / 200 = 1,525 h = 91,5 minuti.'),
      mc('Quanti piloti vanno a punti nella gara sprint?', ['Ai primi otto', 'Ai primi dieci', 'Solo al vincitore', 'Ai primi tre'], 0, 'Lo sprint premia gli otto migliori.'),
      order('Ordina le sessioni di un weekend standard', ['Prove libere 1', 'Prove libere 2', 'Prove libere 3', 'Qualifiche', 'Gara'], 'Venerdì: FP1, FP2. Sabato: FP3, qualifiche. Domenica: gara.')
    ],
    test: [
      mc('Quando si svolgono le qualifiche nel formato standard?', ['Il sabato', 'Il venerdì', 'La domenica prima della gara', 'Il giovedì'], 0, 'Dopo FP3 del sabato.'),
      fill('Una gara sprint è lunga circa 100 km. Una gara classica è circa 305 km. Circa quante volte è più corta? (numero intero)', ['3'], '305 / 100 ≈ 3: una gara sprint è circa un terzo.'),
      mc('Perché gli orari delle gare vanno controllati con attenzione?', ['Sono indicati in ora locale del circuito', 'Cambiano ogni minuto', 'Non sono mai pubblicati', 'Sono uguali ovunque'], 0, 'Il fuso orario cambia l’ora corrispondente da noi.'),
      mc('Che cosa si prova nelle prove libere?', ['Assetto, gomme e ritmo gara', 'Solo il pit stop', 'Solo le luci rosse', 'Niente: servono solo al pubblico'], 0, 'Sono sessioni di allenamento e messa a punto.'),
      mc('Nel formato sprint recente, quante sessioni di prove libere ci sono in tutto il weekend?', ['Una', 'Tre', 'Due', 'Nessuna'], 0, 'Solo FP1; poi le qualifiche sprint.'),
      mc('Quante auto passano da Q2 a Q3?', ['10', '5', '15', '20'], 0, 'Dopo Q2 ne restano 10.'),
      mc('Quanti Gran Premi possono essere in calendario in una stagione (stagioni recenti)?', ['Fino a 24', 'Esattamente 5', 'Circa 50', 'Solo 12'], 0, 'Ordine di grandezza: poco più di venti.')
    ]
  });

  /* ---------- 3 · Squadre, piloti e ruoli ---------- */
  C.addTopic({
    id: 'f1-squadre-piloti-ruoli', subject: 'f1', stage: 'L0', minutes: 12,
    title: 'Squadre, piloti e ruoli',
    summary: 'Scuderia e costruttore, team principal, ingegnere di pista, meccanici, piloti titolari e di riserva, motori e squadre clienti.',
    objectives: ['Spiegare la differenza tra scuderia e costruttore', 'Descrivere i ruoli principali in una squadra', 'Capire che cos’è una squadra cliente per i motori'],
    prereq: ['f1-il-weekend-di-gara'],
    pages: [
      { h: 'Scuderia e costruttore', b: `In F1 si usano due parole vicine ma non identiche.\n\n- La **scuderia** (o *squadra*, in inglese *team*) è l’organizzazione che iscrive le auto al campionato, ha i piloti, i meccanici e gli ingegneri. È chi **gareggia**.\n- Il **costruttore** (*constructor*) è il nome con cui l’auto è iscritta e con cui i punti contano per il campionato costruttori: indica chi **progetta e costruisce** la vettura secondo le regole del campionato.\n\nIn molti casi le due cose coincidono: la squadra X progetta e costruisce l’auto, e anche corre.\n\nLa differenza si vede nei **motori**: l’unità motrice (*power unit*) può essere costruita da un’altra azienda. Per esempio, una scuderia può comprare i motori da una casa automobilistica più grande.\n\n> Regola pratica: la **scuderia** è la squadra sul campo; il **costruttore** è il nome sotto cui l’auto e i punti sono registrati.` },
      { h: 'Il team principal', b: `Il **team principal** (letteralmente «capo della squadra») è il **responsabile** della squadra. È un dirigente: non guida e non ripara l’auto, ma decide la linea.\n\nChe cosa fa:\n\n- coordina ingegneri, meccanici, direttore tecnico e strateghi;\n- rappresenta la squadra davanti alla FIA, al promotore e ai media;\n- partecipa alle riunioni con gli altri capi squadra e con i dirigenti del campionato;\n- ha l’ultima parola sulle scelte importanti, anche in gara;\n- gestisce il budget e i rapporti con gli sponsor.\n\nDurante la gara siede al **muretto dei box** (*pit wall*): una postazione con schermi, accanto alla corsia dei box, da cui lui e gli altri responsabili seguono la corsa e parlano con il pilota via radio.\n\nPer capire: è un allenatore e direttore allo stesso tempo.` },
      { h: 'L’ingegnere di pista e la strategia', b: `Ogni pilota ha un **ingegnere di pista** (*race engineer*), cioè la persona che lo accompagna durante tutto il weekend e gli parla alla **radio**.\n\nIl suo lavoro:\n\n- traduce le **sensazioni del pilota** («il retro scivola») in modifiche tecniche all’auto;\n- controlla la **telemetria** (i dati inviati dall’auto durante la corsa: velocità, temperature, pressioni);\n- dà al pilota informazioni su avversari, gomme e regolazioni;\n- tiene la comunicazione chiara e breve.\n\nAccanto c’è l’**ingegnere di strategia** (*strategist*), che decide **quando fermarsi ai box** e con quali gomme, simulando molte possibilità. Spesso lavora con più persone anche dalla sede della squadra.\n\n> Esempio di messaggio radio: «Box, box questo giro, gomme dure.» Significa: entra ai box adesso e monta le dure.` },
      { h: 'I meccanici e il pit stop', b: `I **meccanici** montano, controllano e riparano l’auto in tutto il weekend. Una squadra ha diverse decine di persone al circuito, e molte altre nella **fabbrica** (la sede), che progetta e produce i pezzi.\n\nDurante la gara, la squadra di sosta (*pit crew*) conta circa **venti** persone, che si occupano di:\n\n- **sollevare** l’auto con i cric anteriore e posteriore;\n- **cambiare le quattro gomme**: per ogni ruota c’è chi la toglie, chi monta la nuova e chi regge la pistola pneumatica;\n- eventuali regolazioni (per esempio dell’ala anteriore).\n\nUn pit stop ben fatto dura circa **2–3 secondi** di auto ferma: il record assoluto è poco sopra **1,8 secondi** (ordine di grandezza). L’intero passaggio dai box, comprensivo della corsia, costa però circa 20 secondi di tempo totale.\n\nGli errori sono rari ma pesano molto: una ruota montata male può far perdere la gara.` },
      { h: 'Piloti titolari', b: `Ogni squadra schiera **due piloti titolari** (*race drivers*) per tutta la stagione. Sono i due che guidano in qualifica e in gara.\n\n- Sono **compagni di squadra** (*teammates*), ma anche i **primi rivali**: hanno la stessa auto, quindi il confronto è diretto.\n- Il loro risultato conta sia per il campionato piloti sia (sommato) per quello costruttori.\n- Devono rispettare gli ordini della squadra in determinate situazioni (per esempio sulla strategia).\n\nIl pilota non guida soltanto: collabora con gli ingegneri, ripete i test, partecipa a eventi con gli sponsor, fa allenamento fisico (collo, schiena, resistenza) e al simulatore.\n\nIl contratto con la squadra stabilisce durata e condizioni. Alcuni piloti restano molti anni nella stessa squadra, altri cambiano più volte.\n\nRicorda che ci sono solo circa **venti** posti di titolare nel mondo.` },
      { h: 'Pilota di riserva e collaudatore', b: `Oltre ai due titolari, ogni squadra ha un **pilota di riserva** (*reserve driver*): una persona preparata a sostituire un titolare in caso di malattia, infortunio o altro impedimento.\n\nIl riserva:\n\n- partecipa ai weekend, o è reperibile, e conosce bene l’auto;\n- spesso lavora anche al **simulatore** nella fabbrica, un computer molto avanzato che riproduce l’auto e le piste;\n- in alcune occasioni può guidare nelle **prove libere** al posto di un titolare (le regole prevedono presenze di giovani piloti nelle prove libere).\n\nIl **collaudatore** (*test driver*) è chi prova l’auto o le novità tecniche fuori dai weekend, nei limiti fissati dal regolamento (i test in pista sono molto limitati).\n\nUn pilota di riserva può diventare titolare: molti hanno iniziato così.` },
      { h: 'Motori e squadre clienti', b: `Il **motore** della F1 si chiama **power unit** (unità motrice): è un motore a combustione ibrido con parti elettriche. Costruirlo è molto costoso e richiede competenze rare, quindi non tutte le squadre lo producono da sole.\n\nPer questo esiste il rapporto **fornitore – cliente**:\n\n- Un **costruttore di motori** (di solito una grande casa automobilistica) progetta la power unit.\n- Una **squadra cliente** paga per **avere i motori** e li monta sulla propria auto, che progetta e costruisce da sé.\n\nÈ una situazione molto comune: nelle stagioni recenti, più squadre usavano motori costruiti da un’altra azienda. Accade anche che la stessa casa fornisca più squadre contemporaneamente.\n\n> Un esempio storico: la McLaren ha corso per molti anni con motori Mercedes, pur essendo una scuderia autonoma.\n\nIl fornitore dà anche assistenza tecnica ai clienti. Chi è cliente non ha «la stessa auto» del fornitore: telaio e aerodinamica sono diversi.` },
      { h: 'La fabbrica e i costi', b: `Quello che si vede al circuito è soltanto una parte del lavoro. Nella **fabbrica** (*factory*) lavorano centinaia di persone: progettisti, aerodinamici, esperti di materiali, programmatori, addetti alla logistica.\n\nI gruppi principali:\n\n- **Progettazione**: disegna l’auto e le sue evoluzioni durante l’anno.\n- **Produzione**: costruisce i pezzi, spesso in carbonio.\n- **Aerodinamica**: studia l’aria con simulazioni al computer e in galleria del vento.\n- **Dati e simulazione**: prepara le strategie.\n\nPer evitare che le squadre più ricche vincano soltanto grazie ai soldi, esiste il **tetto di spesa** (*budget cap*): un limite annuo alle spese, nel regolamento recente dell’ordine di **135 milioni di dollari** (con alcune spese escluse, come quelle dei piloti e dei dirigenti più pagati).\n\nIn sintesi: un’auto sul circuito è il risultato di un lavoro di tantissime persone.` }
    ],
    exercises: [
      mc('Che cos’è la scuderia (team)?', ['L’organizzazione che iscrive e fa correre le auto', 'Un tipo di gomma', 'Il circuito', 'Il giudice della gara'], 0, 'È la squadra con piloti, meccanici e ingegneri.'),
      mc('Chi è il team principal?', ['Il responsabile della squadra', 'Il pilota più veloce', 'Un meccanico', 'Il commissario FIA'], 0, 'Coordina, rappresenta la squadra e decide sulle questioni importanti.'),
      mc('Che cosa fa l’ingegnere di pista?', ['Parla al pilota alla radio e traduce le sue sensazioni in regolazioni', 'Guida l’auto in prova', 'Cambia le gomme', 'Arbitra la gara'], 0, 'È il collegamento tra pilota e squadra tecnica.'),
      mc('A che cosa serve il pilota di riserva?', ['A sostituire un titolare se non può correre', 'A guidare in gara insieme ai titolari', 'A dare i punti', 'A scegliere le gomme'], 0, 'È una figura di emergenza e di sviluppo.'),
      fill('Quanti piloti titolari schiera ogni squadra?', ['2', 'due'], 'Ogni scuderia ha due piloti titolari.'),
      fill('In una sosta ai box lavorano circa quante persone (ordine di grandezza)? Scrivi il numero.', ['20', 'venti'], 'Una squadra di sosta conta circa venti persone.'),
      mc('Che cos’è una squadra cliente?', ['Una squadra che compra i motori da un altro costruttore', 'Una squadra che compra anche i piloti', 'Una squadra senza auto', 'Una squadra di tifosi'], 0, 'Progetta la propria auto ma usa la power unit di un altro.'),
      mc('Che cosa limita il budget cap?', ['Le spese annuali della squadra', 'La velocità massima', 'Il numero di tifosi', 'I giri di qualifica'], 0, 'Un tetto annuo alle spese, per ridurre il divario tra squadre ricche e povere.'),
      mc('Dove siede il team principal in gara?', ['Al muretto dei box', 'Sulla vettura', 'In tribuna con gli sponsor', 'Nel box della FIA'], 0, 'Il pit wall è la postazione con gli schermi, accanto ai box.'),
      mc('Il pit stop è, in genere, lungo di auto ferma circa:', ['2–3 secondi', '20 secondi', '1 minuto', '10 minuti'], 0, 'L’auto ferma sta pochi secondi, ma l’intera sosta costa circa 20 secondi.'),
      order('Ordina i passaggi di un pit stop', ['Il pilota entra nella corsia dei box', 'Rallenta al limite di velocità', 'Si ferma nel suo box', 'I meccanici cambiano le gomme', 'L’auto riparte'], 'Dall’ingresso nella corsia box alla ripartenza.')
    ],
    test: [
      fill('Dieci squadre, ciascuna con 2 piloti titolari. Quanti piloti titolari in tutto?', ['20', 'venti'], '10 × 2 = 20.'),
      mc('Che cosa significa che un pilota e il suo compagno di squadra sono «primi rivali»?', ['Hanno la stessa auto, quindi il confronto è diretto', 'Non si parlano mai', 'Corrono in squadre diverse', 'Non possono finire a punti insieme'], 0, 'Con la stessa auto, il confronto misura il pilota.'),
      mc('Che cosa fa la telemetria?', ['Invia dati dall’auto alla squadra durante la corsa', 'Misura la distanza del circuito', 'Dà le penalità', 'Cambia le gomme'], 0, 'Sono dati su velocità, temperature, pressioni, usati dagli ingegneri.'),
      mc('Dove lavorano molti progettisti di una squadra?', ['Nella fabbrica (sede della squadra)', 'Solo sul circuito', 'In tribuna', 'Nei box della concorrenza'], 0, 'Al circuito c’è solo una parte del personale.'),
      mc('Che cosa è la power unit?', ['Il motore ibrido della monoposto', 'Il volante', 'Il sedile', 'L’ala posteriore'], 0, 'Un motore a combustione con parti elettriche.'),
      mc('Un team cliente per i motori ha un’auto identica a quella del fornitore?', ['No: telaio e aerodinamica sono propri', 'Sì, sempre', 'Sì, ma con motore diverso', 'Dipende dal pilota'], 0, 'Compra la power unit, non l’intera vettura.'),
      mc('A che cosa serve il simulatore nella fabbrica?', ['A far provare auto e piste ai piloti senza uscire dalla sede', 'A fare le gare ufficiali', 'A assegnare i punti', 'A lavare le gomme'], 0, 'Riproduce l’auto e permette lavoro di sviluppo e preparazione.')
    ]
  });

  /* ---------- 4 · Il sistema di punti ---------- */
  C.addTopic({
    id: 'f1-sistema-di-punti', subject: 'f1', stage: 'L0', minutes: 12,
    title: 'Il sistema di punti',
    summary: 'Come si assegnano i punti in gara e nello sprint, che cosa è cambiato con il giro veloce e come si calcolano le classifiche.',
    objectives: ['Ricordare la scala dei punti della gara e dello sprint', 'Sapere che dal 2025 non c’è più il punto per il giro veloce', 'Calcolare punti di piloti e squadre in esempi concreti'],
    prereq: ['f1-squadre-piloti-ruoli'],
    pages: [
      { h: 'Perché servono i punti', b: `Il campionato dura molte gare. Per decidere chi vince il titolo servono i **punti**: un numero assegnato a ogni pilota in base al **piazzamento**.\n\nIl principio è semplice: chi arriva più in alto prende più punti, e **solo i migliori** ne ricevono. Nelle stagioni recenti, in una gara normale vanno a punti i **primi 10** classificati.\n\nAvere un sistema di punti permette di premiare sia chi vince sia chi è **costante**: arrivare sempre quinto o sesto fa accumulare punti, mentre un ritiro dà zero.\n\nI valori che vedi in questa lezione sono quelli del **regolamento in vigore nelle stagioni recenti**. Il sistema di punti è cambiato più volte nella storia della F1: i valori attuali non sono sempre gli stessi di decenni fa.` },
      { h: 'La scala dei punti in gara', b: `Ecco i punti assegnati ai primi dieci classificati in un **Gran Premio**:\n\n| Posizione | Punti |\n|---|---|\n| 1° | **25** |\n| 2° | **18** |\n| 3° | **15** |\n| 4° | **12** |\n| 5° | **10** |\n| 6° | **8** |\n| 7° | **6** |\n| 8° | **4** |\n| 9° | **2** |\n| 10° | **1** |\n\nDall’11° in poi: **0 punti**.\n\n> La somma di tutti i punti distribuiti è 25 + 18 + 15 + 12 + 10 + 8 + 6 + 4 + 2 + 1 = **101** per ogni Gran Premio.\n\nLa differenza tra primo e secondo è 7 punti, quella tra secondo e terzo è 3: vincere vale molto più che arrivare secondo.\n\nPer essere classificato bisogna avere percorso almeno il **90%** della distanza del vincitore: chi si ferma troppo presto non è classificato.` },
      { h: 'I punti della gara sprint', b: `Nei weekend con **sprint** esiste una seconda scala, più corta, perché la gara è più breve. Vanno a punti i **primi otto**:\n\n| Posizione | Punti |\n|---|---|\n| 1° | **8** |\n| 2° | **7** |\n| 3° | **6** |\n| 4° | **5** |\n| 5° | **4** |\n| 6° | **3** |\n| 7° | **2** |\n| 8° | **1** |\n\n> La somma dei punti dello sprint è 8 + 7 + 6 + 5 + 4 + 3 + 2 + 1 = **36**.\n\nIl massimo ottenibile da un pilota in un weekend sprint è quindi 25 + 8 = **33** punti.\n\nI punti dello sprint si sommano a quelli della gara della domenica e valgono per entrambi i titoli (piloti e costruttori).` },
      { h: 'Il giro veloce: cosa è cambiato', b: `Il **giro veloce** (*fastest lap*) è il giro più rapido tra tutti quelli compiuti in gara da un pilota.\n\nPer alcune stagioni, il pilota con il giro veloce otteneva **1 punto extra**, a condizione di arrivare nei **primi dieci**. Dal **2025 questo punto non esiste più**: il giro veloce resta un record e un titolo d’onore, ma non dà punti.\n\n> Quindi nel 2025 il massimo che un pilota può prendere in una gara senza sprint è **25** punti (e non più 26).\n\nPerché fu tolto? Perché a volte spingeva le squadre a fare soste apposite per cercarlo, alterando la corsa.\n\nSe leggi vecchi articoli o statistiche, ricordati che il punto per il giro veloce può comparire nei risultati di stagioni precedenti: controlla sempre l’anno.` },
      { h: 'Esempi di calcolo: un pilota', b: `Calcoliamo i punti di un pilota nel corso di tre weekend.\n\n> Gran Premio 1: 3° posto → **15**\n> Gran Premio 2 (weekend sprint): sprint 5° → **4**, gara 2° → **18**; totale weekend = 22\n> Gran Premio 3: 11° posto → **0**\n\nTotale: 15 + 22 + 0 = **37 punti**.\n\nSecondo esempio. Il pilota A vince la gara (25), il pilota B arriva 4° (12) e vince lo sprint (8). Chi ha più punti nel weekend?\n\n- A: 25\n- B: 12 + 8 = **20**\n\nA guadagna 5 punti in più di B.\n\nSuggerimento: scrivi sempre i punti di ogni sessione e **somma in colonna**, partendo dallo sprint (se c’è) e poi la gara.` },
      { h: 'Esempi di calcolo: una squadra', b: `La squadra ottiene la **somma dei punti dei suoi due piloti**.\n\n> GP 1: piloti 2° e 6° → 18 + 8 = **26**\n> GP 2: piloti 1° e 10° → 25 + 1 = **26**\n> GP 3: piloti 4° e 9° → 12 + 2 = **14**\n\nTotale della squadra dopo tre gare: 26 + 26 + 14 = **66 punti**.\n\nOsserva: nei primi due Gran Premi il totale è identico (26) ma ottenuto in modo diverso. Una squadra con un pilota molto forte e l’altro debole può dare gli stessi punti di una squadra con due piloti costanti.\n\nPer sapere il distacco tra due squadre basta la sottrazione: se la squadra A ha 140 punti e la B 128, il distacco è 140 − 128 = **12 punti**, meno di una vittoria (25).\n\nOgni weekend, due piloti di una stessa squadra possono portare al massimo 25 + 18 = **43** punti in gara (doppietta 1-2).` },
      { h: 'Parità, gare interrotte e massimi', b: `Alcuni casi particolari.\n\n**Parità**: se due piloti hanno gli stessi punti a fine anno, vince chi ha ottenuto più **vittorie**; se è ancora pari, più secondi posti, poi più terzi, e così via.\n\n**Gara interrotta**: se la gara viene fermata e non può ripartire, i punti dipendono da quanta strada è stata percorsa; per gare molto brevi i punti sono **ridotti** secondo una tabella del regolamento (la tabella può cambiare).\n\n**Penalità**: una penalità di tempo cambia l’ordine finale e quindi i punti, perché si applica prima di classificare.\n\n**Massimo teorico**: se un pilota vincesse tutto in una stagione con 24 gare e 6 sprint, farebbe 24 × 25 + 6 × 8 = 600 + 48 = **648 punti**. Non è mai successo nulla del genere: è solo un calcolo per fissare le idee.\n\nIl numero di sprint cambia da stagione a stagione, per cui il massimo cambia.` },
      { h: 'Riepilogo e come ricordare', b: `**Gara**: 25 – 18 – 15 – 12 – 10 – 8 – 6 – 4 – 2 – 1 (primi dieci).\n\n**Sprint**: 8 – 7 – 6 – 5 – 4 – 3 – 2 – 1 (primi otto).\n\n**Giro veloce**: dal 2025 **nessun punto**.\n\nSuggerimenti per ricordarli:\n\n- Dal 1° al 4° posto i punti scendono di 7, poi 3, poi 3 (25, 18, 15, 12).\n- Dal 4° al 9° scendono di 2 in 2 (12, 10, 8, 6, 4, 2).\n- Il 10° prende 1 punto.\n- Per lo sprint basta ricordare «da 8 a 1, di uno in uno».\n\nDue classifiche: i punti dei **piloti** vanno a ciascuno; i punti dei **costruttori** sono la somma dei due piloti della squadra.\n\nRicorda sempre che il sistema può essere cambiato dalla FIA da una stagione all’altra.` }
    ],
    exercises: [
      fill('Quanti punti prende chi arriva 3° in un Gran Premio?', ['15'], 'La scala è 25-18-15-12-10-8-6-4-2-1.'),
      fill('Quanti punti prende chi arriva 10° in un Gran Premio?', ['1'], 'Il decimo prende un punto.'),
      fill('Quanti punti prende chi arriva 5° in una gara sprint?', ['4'], 'Sprint: 8-7-6-5-4-3-2-1.'),
      fill('Un pilota arriva 3° in un GP e 5° nello sprint dello stesso weekend. Quanti punti in totale?', ['19'], '15 + 4 = 19.'),
      fill('Una squadra ha i piloti al 2° e al 6° posto in un GP. Quanti punti prende?', ['26'], '18 + 8 = 26.'),
      fill('Quanti punti si distribuiscono in totale in un Gran Premio ai primi dieci?', ['101'], '25+18+15+12+10+8+6+4+2+1 = 101.'),
      fill('Quanti punti si distribuiscono in totale nello sprint ai primi otto?', ['36'], '8+7+6+5+4+3+2+1 = 36.'),
      mc('Dal 2025, il pilota con il giro veloce ottiene:', ['Nessun punto', '1 punto', '2 punti', '3 punti'], 0, 'Il punto extra per il giro veloce è stato abolito.'),
      mc('Quanti piloti vanno a punti in una gara normale (stagioni recenti)?', ['10', '8', '6', '15'], 0, 'I primi dieci classificati.'),
      mc('Quanti punti prende la 4ª posizione di una gara sprint?', ['5', '12', '4', '8'], 0, 'Sprint: 4° = 5 punti (in gara 4° = 12).'),
      order('Ordina i punti della gara dal 1° al 5° posto', ['25', '18', '15', '12', '10'], 'Sono i primi cinque valori della scala.')
    ],
    test: [
      fill('Un pilota fa 1° in gara e 8° nello sprint dello stesso weekend. Quanti punti?', ['26'], '25 + 1 = 26.'),
      fill('Un pilota fa 7° in GP e 3° nello sprint. Quanti punti in totale?', ['12'], '6 + 6 = 12.'),
      fill('Una squadra ha piloti al 4° e al 9° posto in gara. Quanti punti?', ['14'], '12 + 2 = 14.'),
      fill('Un pilota vince tre GP (senza sprint). Quanti punti?', ['75'], '3 × 25 = 75.'),
      mc('Quanti punti prende il 9° in un GP?', ['2', '1', '4', '0'], 0, '9° = 2 punti.'),
      mc('Quale piazzamento dello sprint vale 2 punti?', ['7°', '2°', '9°', '10°'], 0, 'Sprint: 7° = 2 punti.'),
      mc('Quale squadra è avanti: A con 140 punti o B con 128? E di quanto?', ['A, di 12 punti', 'B, di 12 punti', 'A, di 25 punti', 'Sono pari'], 0, '140 − 128 = 12.'),
      mc('Perché una doppietta (1° e 2°) vale 43 punti per la squadra?', ['25 + 18 = 43', '25 + 25 = 50', '18 + 15 = 33', '25 × 2 = 50'], 0, 'Si sommano i punti dei due piloti.')
    ]
  });

  /* ---------- 5 · Bandiere e segnali ---------- */
  C.addTopic({
    id: 'f1-bandiere-e-segnali', subject: 'f1', stage: 'L0', minutes: 12,
    title: 'Le bandiere e i segnali',
    summary: 'Giallo, rosso, blu, scacchi, nero, bianco, verde e le procedure di Safety Car e Virtual Safety Car: che cosa significano e che cosa accade in pista.',
    objectives: ['Riconoscere il significato delle principali bandiere', 'Spiegare che cosa cambia in pista con safety car e VSC', 'Capire perché i segnali sono essenziali per la sicurezza'],
    prereq: ['f1-sistema-di-punti'],
    pages: [
      { h: 'Perché esistono le bandiere', b: `Le auto di F1 vanno velocissime e i piloti non vedono tutto quello che c’è oltre la curva. Per questo lungo la pista ci sono **commissari di percorso** (i *marshals*), persone posizionate in postazioni numerate che, con le **bandiere**, avvisano i piloti di un pericolo o di un’informazione importante.\n\nOggi si usano anche **pannelli luminosi** (luci sul bordo pista e sul volante del pilota) che mostrano lo stesso segnale, ma le bandiere sono ancora il linguaggio base.\n\nLe regole sono definite dalla FIA e sono valide per tutti i circuiti: un pilota deve riconoscere subito i colori e reagire senza esitare.\n\n> Nei prossimi paragrafi: giallo (pericolo), rosso (stop), blu (lasciar passare), scacchi (fine), nero (squalifica), bianco (veicolo lento), verde (via libera). Poi la safety car.` },
      { h: 'Bandiera gialla', b: `La **bandiera gialla** significa: **pericolo, rallentare**. Viene agitata dal commissario nel punto in cui c’è un ostacolo (un’auto ferma, detriti, un pilota fuori pista).\n\nQuando c’è la gialla un pilota deve:\n\n- **lasciare l’acceleratore**, ridurre la velocità e essere pronto a cambiare direzione;\n- **non superare** fino a dopo il punto del pericolo (il sorpasso sotto bandiera gialla è proibito);\n- in generale, non cercare di migliorare il proprio tempo nel settore interessato.\n\nLa **doppia gialla** (due bandiere agitate) è più grave: il pilota deve rallentare molto ed essere pronto a **fermarsi** perché il pericolo può occupare parte della pista.\n\n> Esempio: un’auto va in testacoda in curva 5. Il commissario agita la gialla; chi arriva rallenta e non sorpassa fino al passaggio dell’auto ferma.` },
      { h: 'Bandiera rossa', b: `La **bandiera rossa** significa: **sessione fermata**. Si usa quando la pista non è più sicura (un incidente grave, detriti molto estesi, pioggia fortissima).\n\nCosa succede:\n\n- Tutti i piloti devono **rientrare ai box** in modo lento e controllato, senza sorpassare.\n- In gara le auto si fermano nella **corsia dei box**, in fila, alla fine della corsia, dove la squadra può **cambiare le gomme** e fare riparazioni.\n- La gara riprende solo quando i commissari lo decidono, con una **nuova partenza da fermi** (*standing restart*), in base al regolamento recente.\n\nIl tempo di sospensione non conta nel limite di durata di 2 ore, ma c’è un limite totale di **3 ore** di tempo dalla partenza.\n\nDurante le qualifiche e le prove la rossa ferma l’orologio: la sessione riparte quando la pista è sicura. Se non si riesce a ripartire, la gara può essere conclusa in anticipo e i punti sono assegnati con la tabella ridotta.` },
      { h: 'Bandiera blu', b: `La **bandiera blu** significa: **lascia passare**. Viene mostrata a un pilota **doppiato**, cioè a uno che sta per essere raggiunto da un avversario che ha già compiuto un giro in più.\n\nEsempio. Il leader sta percorrendo il giro 40 e raggiunge un pilota che ne ha completati solo 38: quest’ultimo è **doppiato**, cioè ha almeno un giro di ritardo. Per non rallentare il leader, il doppiato deve lasciarlo passare **in tempi brevi**, senza ostacolarlo (nelle regole, dopo pochi segnali blu).\n\nPerché è così? Perché le posizioni in classifica sono determinate da **giri e distacco**, e un pilota doppiato non sta lottando con il leader. Lasciarlo passare evita che il leader perda tempo.\n\nIgnorare la blu può portare a una penalità. In qualifica la blu si mostra a chi è in giro lento e potrebbe ostacolare chi sta facendo un giro veloce.` },
      { h: 'Bandiera a scacchi', b: `La **bandiera a scacchi** (a quadri bianchi e neri) significa: **fine**. Viene mostrata al traguardo, di solito sventolata da una persona importante o da un ospite, al primo pilota che taglia la linea quando ha completato il numero di giri previsto (o scaduto il tempo massimo).\n\nDopo la bandiera a scacchi, ogni pilota percorre un ultimo giro lento (**giro di rientro**, *in-lap*) e si ferma al **parco chiuso**, dove l’auto viene controllata dai tecnici FIA.\n\nIn pratica:\n\n- La bandiera a scacchi viene mostrata al **vincitore**: gli altri la ricevono quando tagliano il traguardo dopo di lui.\n- Il giro di rientro serve a raffreddare l’auto e a fare festa con i tifosi.\n- Il podio, con i primi tre, e il parco chiuso completano la procedura.\n\nIn qualifica e prove libere, a scacchi indica la fine della sessione.` },
      { h: 'Bandiera nera e le sue varianti', b: `La **bandiera nera** significa: **squalifica**. Viene esposta con il numero di gara del pilota. Quel pilota deve rientrare ai box al giro successivo e non può più continuare la gara. È una sanzione molto grave, rara in F1 oggi.\n\nEsistono due versioni particolari:\n\n- **Nera con un cerchio arancione**: segnala al pilota un **problema meccanico** pericoloso alla sua auto (per esempio un pezzo che si sta staccando). Deve rientrare ai box per un controllo.\n- **Nera e bianca in diagonale**: è un **avvertimento** per comportamento antisportivo. Non squalifica, ma una seconda segnalazione può portare a conseguenze più gravi.\n\nIn pratica oggi molte sanzioni vengono comunicate via radio e con messaggi della direzione gara; la bandiera nera resta il simbolo ufficiale della squalifica.\n\n> Ricorda: nera = fuori. Nera con cerchio arancione = problema all’auto. Nera e bianca = ammonizione.` },
      { h: 'Bianca, verde, gialla e rossa a strisce', b: `Altre bandiere da conoscere:\n\n- **Bianca**: c’è un **veicolo lento** sul percorso (per esempio un’auto di soccorso o una macchina con un problema). Non è un pericolo immediato, ma il pilota deve fare attenzione.\n- **Verde**: **via libera**. Indica che il pericolo è passato e che la pista è di nuovo sicura (viene mostrata dopo una gialla, quando si può accelerare e sorpassare).\n- **Gialla e rossa a strisce verticali**: c’è una **superficie scivolosa** (acqua, olio, detriti sottili). Il pilota deve fare attenzione al grip.\n\nRiassumendo i colori:\n\n| Colore | Significato |\n|---|---|\n| Gialla | pericolo, rallenta, non sorpassare |\n| Rossa | sessione fermata |\n| Blu | lascia passare |\n| Scacchi | fine |\n| Nera | squalifica |\n| Bianca | veicolo lento |\n| Verde | via libera |\n| Gialla/rossa a strisce | pista scivolosa |` },
      { h: 'Safety car e virtual safety car', b: `Quando un incidente richiede più tempo per essere gestito ma non è necessaria la bandiera rossa, la direzione gara può inviare la **safety car** (SC): un’auto speciale che entra in pista e **guida il gruppo a velocità ridotta**.\n\nCosa succede con la **safety car**:\n\n- Tutti devono seguire in fila dietro la SC, senza sorpassare; i distacchi si **compattano**.\n- Le soste ai box costano meno tempo, perché gli altri vanno piano: spesso molte squadre ne approfittano.\n- Quando la pista è libera, la SC rientra ai box: la gara riparte con la **ripartenza** lanciata.\n\nLa **virtual safety car** (VSC) è una versione senza auto fisica: i piloti devono **rallentare** e restare sopra un tempo minimo (*delta*) indicato sul volante, senza sorpassare. È usata per incidenti più piccoli, come un’auto ferma a bordo pista.\n\n> Differenza: con la SC il gruppo si **ricompatta**; con la VSC i **distacchi restano** quasi uguali.` }
    ],
    exercises: [
      mc('Che cosa significa la bandiera gialla?', ['Pericolo: rallentare e non sorpassare', 'Fine della gara', 'Lascia passare', 'Squalifica'], 0, 'Gialla = pericolo sulla pista.'),
      mc('Che cosa significa la bandiera rossa?', ['Sessione fermata', 'Via libera', 'Veicolo lento', 'Fine della gara'], 0, 'La rossa ferma la sessione quando la pista non è sicura.'),
      mc('A chi si mostra la bandiera blu?', ['Al pilota doppiato che deve lasciar passare il più veloce', 'Al leader della gara', 'Al pilota squalificato', 'Al pilota che fa il giro veloce'], 0, 'Blu = lascia passare.'),
      mc('Che cosa significa la bandiera a scacchi?', ['Fine della gara o della sessione', 'Inizio della gara', 'Squalifica', 'Pericolo'], 0, 'È la bandiera del traguardo.'),
      mc('Che cosa significa la bandiera nera?', ['Squalifica del pilota', 'Pista scivolosa', 'Giro veloce', 'Safety car'], 0, 'Nera con il numero di gara = squalificato.'),
      mc('Che cosa segnala la bandiera bianca?', ['Un veicolo lento sul percorso', 'Fine della gara', 'Pioggia', 'Penalità'], 0, 'Veicolo lento davanti.'),
      mc('Quando si mostra la bandiera verde?', ['Quando il pericolo è passato e la pista è libera', 'Alla partenza di una gara con bandiera rossa', 'Al vincitore', 'Quando inizia il giro veloce'], 0, 'Verde = via libera dopo un pericolo.'),
      mc('Cosa succede ai distacchi con la safety car?', ['Il gruppo si compatta', 'Aumentano molto', 'Restano uguali', 'Si azzerano le gomme'], 0, 'Le auto seguono la SC in fila, quindi i vantaggi si annullano.'),
      mc('Che cosa distingue la VSC dalla safety car?', ['Non c’è un’auto davanti: i piloti rispettano un tempo minimo', 'È più veloce', 'Si usa solo in qualifica', 'Non vieta i sorpassi'], 0, 'Nella VSC i piloti rallentano ma non si compattano.'),
      mc('Cosa può fare la squadra durante una bandiera rossa in gara?', ['Cambiare le gomme e riparare l’auto', 'Niente, l’auto è bloccata', 'Cambiare pilota', 'Annullare la gara'], 0, 'Le auto stanno ai box e possono essere lavorate.'),
      order('Ordina i passi quando il pilota vede la bandiera gialla', ['Vede la bandiera', 'Alza il piede dall’acceleratore', 'Passa il punto del pericolo senza sorpassare', 'Riceve la verde', 'Accelera di nuovo'], 'Prima rallenta, poi quando ripassa verde può riprendere.')
    ],
    test: [
      mc('Che cosa significa la doppia gialla?', ['Pericolo grave: pronti a fermarsi', 'Via libera', 'Fine gara', 'Veicolo lento'], 0, 'Due bandiere indicano un pericolo più esteso.'),
      mc('Se un pilota ignora la blu, che cosa rischia?', ['Una penalità', 'Un premio', 'Niente', 'La pole position'], 0, 'Ignorare la blu è sanzionabile.'),
      mc('Che cosa significa la bandiera nera con cerchio arancione?', ['Problema meccanico: rientrare ai box', 'Squalifica', 'Fine della gara', 'Via libera'], 0, 'Segnala un guasto pericoloso.'),
      mc('Che cosa è un pilota doppiato?', ['Uno raggiunto da un avversario che ha un giro in più', 'Uno che ha vinto', 'Uno che sorpassa', 'Uno senza gomme'], 0, 'È uno che ha un giro in meno rispetto al leader che lo raggiunge.'),
      mc('Quale bandiera avvisa di una superficie scivolosa?', ['Gialla e rossa a strisce', 'Bianca', 'Blu', 'Verde'], 0, 'È la bandiera a strisce gialle e rosse.'),
      mc('Perché con la safety car molte squadre fanno la sosta?', ['Perdono meno tempo perché gli altri vanno piano', 'È obbligatorio', 'Perché le gomme si rompono', 'Per cambiare pilota'], 0, 'La sosta costa meno distacco.'),
      mc('Dopo la bandiera a scacchi che cosa fanno i piloti?', ['Un giro di rientro e poi il parco chiuso', 'Ricominciano la gara', 'Si fermano subito in pista', 'Vanno ai box della concorrenza'], 0, 'Il giro di rientro porta le auto ai controlli.')
    ]
  });

  /* ---------- 6 · Il circuito ---------- */
  C.addTopic({
    id: 'f1-il-circuito', subject: 'f1', stage: 'L0', minutes: 12,
    title: 'Il circuito',
    summary: 'Curve, rettilinei, settori, cordoli, vie di fuga, zone DRS e tipi di circuiti; come leggere una mappa di una pista.',
    objectives: ['Riconoscere le parti di un circuito', 'Distinguere circuiti permanenti, cittadini e misti', 'Leggere una mappa con curve, settori e zone DRS'],
    prereq: ['f1-bandiere-e-segnali'],
    pages: [
      { h: 'Com’è fatta una pista', b: `Un **circuito** è un percorso chiuso, che si percorre più volte (i **giri**). Le parti principali sono:\n\n- la **linea di partenza e arrivo** (*start/finish*), sul rettilineo principale;\n- la **griglia di partenza**, le posizioni dove le auto si schierano;\n- la **corsia dei box** (*pit lane*) con i garage, parallela al rettilineo;\n- il **tracciato**: una sequenza di curve e rettilinei;\n- la **zona di sicurezza**: bordi, vie di fuga, barriere.\n\nLa **lunghezza** di un giro si misura in chilometri: i circuiti di F1 vanno da circa 3 a 7 km. Moltiplicando la lunghezza per il numero di giri si ottiene la distanza di gara.\n\n> Esempio: 5 km × 60 giri = **300 km**. Gli organizzatori scelgono il numero di giri in modo che la distanza superi i 305 km.` },
      { h: 'Le curve', b: `Le curve di un circuito si distinguono per forma e velocità.\n\n- **Tornante** (*hairpin*): curva molto stretta, quasi 180°, che costringe a rallentare moltissimo.\n- **Curva lenta / media / veloce**: dipende dal raggio e dalla velocità con cui si percorre.\n- **Chicane**: due curve ravvicinate in senso opposto (destra-sinistra), nate per rallentare le auto in un punto veloce.\n- **Esse** (a S): una serie di curve che cambiano direzione.\n- **Curva a gomito**: un angolo secco.\n\nOgni curva ha un **punto di corda** (*apex*): il punto più interno della traiettoria, dove il pilota passa più vicino al bordo interno.\n\nLe curve sono **numerate** nell’ordine in cui vengono percorse, a partire dalla prima dopo il traguardo (curva 1, curva 2…). Molte curve celebri hanno anche un nome proprio (per esempio la «Parabolica» a Monza).` },
      { h: 'Rettilinei e velocità', b: `I **rettilinei** sono i tratti dove l’auto può correre alla massima velocità. Nei rettilinei più lunghi le auto raggiungono circa **330–350 km/h** (ordine di grandezza; dipende dal circuito e dall’assetto).\n\nTra un rettilineo e la curva successiva c’è la **staccata** (*braking zone*): il punto dove il pilota frena forte. Dai 300 km/h si può scendere sotto i 100 km/h in pochi secondi.\n\n> Conversione utile: dividendo i km/h per 3,6 si ottengono i metri al secondo. 360 km/h = 100 m/s: in un solo secondo l’auto percorre 100 metri, quasi un campo di calcio.\n\nPer questo le **staccate** e le **uscite di curva** sono i punti dove si guadagna o si perde tempo: un buon pilota accelera presto e frena tardi, senza passare il limite di aderenza.\n\nI circuiti con tanti rettilinei lunghi premiano le auto con poca resistenza all’aria; quelli con tante curve le auto con più carico.` },
      { h: 'I settori', b: `Per misurare le prestazioni, ogni circuito è diviso in **tre settori**, di lunghezza simile. Il tempo del giro è la **somma dei tempi dei tre settori**.\n\n> Esempio: settore 1 = 28,4 s; settore 2 = 34,1 s; settore 3 = 22,5 s.\n> Giro = 28,4 + 34,1 + 22,5 = **85,0 s** (1 minuto e 25 secondi).\n\nI settori servono a:\n\n- vedere **dove** un pilota è più veloce o più lento di un altro;\n- permettere alla televisione di mostrare i tempi mentre il giro è in corso;\n- aiutare i commissari a segnalare le bandiere gialle «per settore».\n\nSul circuito ci sono sensori (**trasponder**) che registrano il passaggio di ogni auto alla fine di ogni settore.\n\nIn televisione compaiono spesso anche i **mini-settori**, più piccoli, per leggere più nel dettaglio dove si guadagna e dove si perde.` },
      { h: 'Cordoli e vie di fuga', b: `Ai bordi della pista ci sono elementi pensati per sicurezza e per guidare il pilota.\n\n- I **cordoli** (*kerbs*) sono strisce rialzate, spesso rosse e bianche, nei punti interni ed esterni delle curve. I piloti le sfiorano per accorciare la traiettoria, ma non devono sfruttarle troppo.\n- I **limiti pista** (*track limits*) sono le linee bianche ai bordi: se un pilota esce del tutto da quella linea e ottiene un vantaggio, il giro può essere cancellato o può arrivare una penalità.\n- Le **vie di fuga** (*run-off*) sono aree dopo il bordo pista, di **asfalto** o **ghiaia**, dove un'auto che esce di strada può rallentare. La ghiaia frena molto e blocca l’auto; l’asfalto permette di rientrare più facilmente.\n- Le **barriere** sono pareti con gomme o materiali assorbenti che attutiscono gli urti.\n\nUna pista moderna è pensata in modo che un errore del pilota non diventi un incidente grave.` },
      { h: 'Le zone DRS', b: `Il **DRS** (*Drag Reduction System*) è un dispositivo dell’ala posteriore: quando si apre, riduce la resistenza dell’aria e fa guadagnare qualche chilometro orario in rettilineo, per favorire i sorpassi.\n\nRegole recenti:\n\n- Si può usare solo nelle **zone DRS** indicate sulla mappa del circuito (di solito uno o più lunghi rettilinei).\n- Il pilota che insegue deve essere a meno di **1 secondo** dall’auto davanti nel **punto di rilevamento** (*detection point*), prima della zona.\n- In gara non è utilizzabile nei primi giri dopo la partenza o dopo una ripartenza.\n- In qualifica e nelle prove è utilizzabile liberamente nelle zone.\n\nAttenzione: il regolamento tecnico cambia nel **2026**, con nuove soluzioni aerodinamiche che sostituiscono il DRS tradizionale. Quanto descritto qui vale per le stagioni fino al 2025.\n\nSulla mappa la zona DRS è di solito evidenziata con un colore sul rettilineo.` },
      { h: 'Tipi di circuiti', b: `Esistono tre grandi famiglie.\n\n**Permanenti**: piste costruite per le corse e usate tutto l’anno (Monza in Italia, Silverstone nel Regno Unito, Spa in Belgio). Hanno ampie vie di fuga e strutture stabili.\n\n**Cittadini** (*street circuits*): usano le strade di una città, chiuse al traffico per il weekend. Esempi: Monaco, Singapore, Baku, Las Vegas. Sono più **stretti**, con muri vicini alla pista e poche vie di fuga: un errore è pagato molto caro.\n\n**Misti**: usano in parte strade normali e in parte aree dedicate (per esempio un parco pubblico).\n\nOrdini di grandezza per tre piste (lunghezza × giri = distanza):\n\n| Pista | Lunghezza | Giri | Distanza |\n|---|---|---|---|\n| Monza | 5,79 km | 53 | circa 307 km |\n| Monaco | 3,34 km | 78 | circa 260 km |\n| Spa | 7,00 km | 44 | circa 308 km |\n\nSe vedi 78 giri a Monaco: 3,337 × 78 ≈ 260 km, minimo previsto per quella gara.` },
      { h: 'Come leggere la mappa di un circuito', b: `Una **mappa** è la vista dall’alto del circuito. Ecco che cosa cercare.\n\n1. **Linea di partenza/arrivo** e **freccia di direzione**: ti dicono in che verso si corre (orario o antiorario).\n2. **Numeri delle curve**: 1, 2, 3… nell’ordine di percorrenza.\n3. **Tre settori**, spesso evidenziati con colori diversi.\n4. **Zone DRS** e **punti di rilevamento**.\n5. **Corsia dei box** e uscita/ingresso.\n6. **Nomi** di curve celebri.\n\nPer capire se un circuito è «veloce» o «tecnico»:\n\n- Molti lunghi **rettilinei** e curve ampie → circuito veloce.\n- Tante curve lente, tornanti e chicane → circuito tecnico e lento.\n\nSe confronti due mappe, osserva anche la **larghezza**: un circuito cittadino sembra più sinuoso e vicino ai muri.\n\nCon un po’ di pratica, guardando la mappa saprai prevedere dove ci saranno i sorpassi: di solito dopo un lungo rettilineo e una staccata forte.` }
    ],
    exercises: [
      mc('Che cos’è un tornante (hairpin)?', ['Una curva molto stretta di quasi 180 gradi', 'Un lungo rettilineo', 'Un tipo di gomma', 'Un settore'], 0, 'Costringe a rallentare moltissimo.'),
      mc('Che cos’è una chicane?', ['Due curve ravvicinate in senso opposto', 'Una zona di sosta', 'Il rettilineo dei box', 'Un tipo di cordolo'], 0, 'Spesso serve a rallentare le auto.'),
      fill('Un giro è lungo 5 km e la gara dura 60 giri. Quanti km è lunga la gara?', ['300'], '5 × 60 = 300.'),
      fill('Un’auto va a 360 km/h. Quanti metri percorre in 1 secondo?', ['100'], '360 / 3,6 = 100 m/s.'),
      fill('Quanti secondi dura un giro con settori 28,4 + 34,1 + 22,5?', ['85', '85,0', '85.0'], '28,4 + 34,1 + 22,5 = 85,0.'),
      fill('Quanti settori ha un circuito di F1?', ['3', 'tre'], 'Ogni circuito è diviso in tre settori.'),
      mc('A che cosa servono i cordoli?', ['A guidare le traiettorie e segnare il bordo pista', 'Ad accelerare le auto', 'A fermare la gara', 'A cambiare le gomme'], 0, 'Sono strisce rialzate ai bordi delle curve.'),
      mc('Che differenza c’è tra una via di fuga di ghiaia e una di asfalto?', ['La ghiaia frena e blocca l’auto, l’asfalto permette di rientrare', 'Sono uguali', 'La ghiaia è più veloce', 'L’asfalto blocca sempre l’auto'], 0, 'Dipende dall’obiettivo: frenare o consentire il rientro.'),
      mc('Quanto distante deve essere un pilota dal precedente, al punto di rilevamento, per usare il DRS (regolamento fino al 2025)?', ['Meno di 1 secondo', 'Meno di 5 secondi', 'Più di 3 secondi', 'Mai, è libero'], 0, 'Per aprire il DRS in gara serve essere entro 1 secondo.'),
      mc('Quale di questi è un circuito cittadino?', ['Monaco', 'Monza', 'Silverstone', 'Spa-Francorchamps'], 0, 'Monaco usa le strade della città.'),
      order('Ordina i passaggi per calcolare la distanza di gara', ['Lunghezza del giro', 'Numero di giri', 'Moltiplica', 'Distanza di gara'], 'Distanza = lunghezza giro × numero di giri.')
    ],
    test: [
      fill('Un circuito è lungo 4 km e si corrono 76 giri. Quanti km è la gara?', ['304'], '4 × 76 = 304.'),
      fill('Un’auto va a 180 km/h. Quanti metri al secondo?', ['50'], '180 / 3,6 = 50.'),
      mc('Qual è la funzione dei settori?', ['Dividere il giro per vedere dove si guadagna o si perde tempo', 'Aumentare i punti', 'Fermare la gara', 'Indicare la sosta'], 0, 'Il tempo di giro è la somma dei tre settori.'),
      mc('Perché i circuiti cittadini sono considerati più rischiosi?', ['Sono stretti, con muri vicini e poche vie di fuga', 'Non hanno curve', 'Non hanno box', 'Sono molto larghi'], 0, 'Un errore ha conseguenze più pesanti.'),
      mc('Dove ci sono più probabilità di sorpasso?', ['Dopo un lungo rettilineo, alla staccata', 'In mezzo a una curva lenta', 'Sul traguardo, sempre', 'Nei box'], 0, 'Chi insegue guadagna velocità e frena più tardi.'),
      mc('Che cosa sono i limiti pista (track limits)?', ['Le linee bianche ai bordi della pista', 'I box delle squadre', 'I punti di rilevamento DRS', 'Le tribune'], 0, 'Se si esce ottenendo vantaggio, il giro può essere cancellato.'),
      mc('Monaco ha circa 3,34 km per giro e 78 giri. Qual è la distanza di gara, circa?', ['260 km', '305 km', '180 km', '350 km'], 0, '3,337 × 78 ≈ 260 km.')
    ]
  });

  /* ---------- 7 · La monoposto in sintesi ---------- */
  C.addTopic({
    id: 'f1-la-monoposto-in-sintesi', subject: 'f1', stage: 'L0', minutes: 12,
    title: 'La monoposto in sintesi',
    summary: 'Che cosa rende una F1 diversa da un’auto stradale: potenza, peso, carico aerodinamico, parti principali e posto di guida con halo, sedile e volante.',
    objectives: ['Confrontare una F1 con un’auto stradale in potenza, peso e aerodinamica', 'Nominare le parti principali della monoposto', 'Descrivere il pilota nell’abitacolo: sedile, halo, volante'],
    prereq: ['f1-il-circuito'],
    pages: [
      { h: 'Non è un’auto stradale', b: `Una **F1** è molto diversa da un’auto che guidi ogni giorno. Una vettura stradale è un compromesso: deve essere comoda, economica, sicura, silenziosa, e deve durare anni. Una F1 ha un solo obiettivo: **andare veloce sul giro**.\n\nDifferenze evidenti:\n\n- ha **un solo posto** e le **ruote scoperte**;\n- è molto **bassa** e molto **leggera**;\n- ha **ali** grandi, davanti e dietro;\n- non ha bagagliaio, aria condizionata, radio, serratura;\n- i pezzi sono fatti di **fibra di carbonio** e leghe speciali, costosissimi;\n- dura poche gare: molte parti vengono sostituite spesso.\n\nIn sostanza, la monoposto è una macchina fatta apposta per correre: tutto ciò che non serve alla velocità è tolto.` },
      { h: 'Potenza e peso', b: `Due numeri contano più di tutti: la **potenza** (quanta forza motrice) e il **peso**.\n\nOrdini di grandezza, per le stagioni recenti:\n\n- La F1 ha una **power unit** da circa **1000 cavalli** (CV) in totale (motore a combustione 1,6 litri V6 turbo più parte elettrica).\n- Il **peso minimo** della vettura, con pilota e senza carburante, è fissato dal regolamento in circa **800 kg** (può cambiare nel tempo).\n- Una normale auto familiare pesa circa 1300–1500 kg e ha 100–150 CV.\n\nSi confronta con il **rapporto peso/potenza**:\n\n> F1: 1000 CV / 800 kg = **1,25 CV per kg**\n> Auto familiare: 150 CV / 1500 kg = **0,1 CV per kg**\n> Rapporto: 1,25 / 0,1 = **12,5 volte** di più.\n\nIl risultato è un’accelerazione enorme: una F1 passa da 0 a 100 km/h in circa **2,5 secondi** e supera i 300 km/h (ordini di grandezza).` },
      { h: 'Il carico aerodinamico', b: `Il vero segreto di una F1 è l’**aerodinamica**: il modo in cui l’aria scorre intorno all’auto.\n\nLe ali e il fondo della vettura creano una forza verso il basso chiamata **carico aerodinamico** (in inglese *downforce*, o *deportanza*). Spinge l’auto contro l’asfalto, come se fosse più pesante, e aumenta l’**aderenza** delle gomme, cioè la forza che le tiene incollate alla strada.\n\nEffetti:\n\n- in curva si può andare molto più veloci, senza uscire di pista;\n- più si va veloci, più il carico aumenta;\n- ad alte velocità il carico può essere **maggiore del peso stesso dell’auto**.\n\nIl prezzo si chiama **resistenza all’aria** (*drag*): più carico c’è, più l’auto fa fatica ad avanzare in rettilineo. Gli ingegneri cercano un compromesso diverso per ogni pista: più carico a Monaco (curve lente), meno a Monza (rettilinei veloci).\n\nAttenzione: «può correre sul soffitto» è un modo di dire teorico, non un fatto pratico.` },
      { h: 'Le parti principali', b: `Elenco semplice delle parti che vedrai nominate in tv.\n\n- **Telaio / scocca** (*monocoque*): il guscio rigido in fibra di carbonio dove sta il pilota; è la «cellula di sopravvivenza».\n- **Power unit**: il motore ibrido, dietro il pilota.\n- **Cambio**: a 8 marce, azionato con le palette del volante.\n- **Ala anteriore** e **ala posteriore**: generano carico.\n- **Fondo**: la parte sotto l’auto, che crea molto carico.\n- **Sospensioni**: collegano le ruote al telaio.\n- **Freni**: dischi in carbonio, che sopportano temperature molto elevate.\n- **Gomme**: le uniche parti a contatto con la pista (4 gomme, con un fornitore unico).\n- **Serbatoio**: in gara il carburante massimo è circa **110 kg**.\n- **Sidepod**: le «pance» laterali con i radiatori.\n\nOgni parte influenza le altre. Se cambia l’aerodinamica, cambia il comportamento dei freni, delle gomme e delle sospensioni.` },
      { h: 'Gomme e freni', b: `Le **gomme** sono l’unico contatto tra l’auto e l’asfalto: tutte le forze di accelerazione, frenata e curva passano per quattro piccole superfici, grandi poco più di una cartolina ciascuna.\n\n- Il fornitore è unico per tutto il campionato (nelle stagioni recenti, Pirelli).\n- Le gomme **asciutte** sono di diverse **mescole** (dure, medie, morbide), riconosciute dal colore sul fianco: **rosso** morbida, **giallo** media, **bianco** dura.\n- Per la pioggia ci sono le **intermedie** (verdi) e le **da bagnato estremo** (blu).\n\nI **freni** sono potentissimi: dai 300 km/h si può scendere a velocità molto basse in pochi secondi. I dischi in carbonio diventano incandescenti e possono superare i 1000 °C (ordine di grandezza).\n\nIl pilota subisce forze pesanti: in frenata e curva può sentire fino a **5–6 g**, cioè un peso fino a cinque o sei volte il proprio.` },
      { h: 'Il pilota nell’abitacolo', b: `Il pilota è seduto molto **sdraiato**, quasi con le gambe all’altezza del busto, a pochi centimetri dal suolo.\n\n- Il **sedile** non è uno schienale qualunque: è **modellato sul corpo di ciascun pilota** con una forma in resina, per sostenerlo durante le forze in curva.\n- Le **cinture di sicurezza** sono a più punti di ancoraggio e lo tengono ben fermo.\n- Il **casco** è omologato e con visiera resistente; indossa anche tuta e guanti ignifughi.\n- Il dispositivo **HANS** protegge il collo negli urti.\n- Dal 2018 c’è l’**halo**, una struttura in titanio a forma di arco sopra la testa del pilota, che protegge da detriti e urti. Pesa circa **7 kg** e ha salvato diversi piloti.\n\nIl pilota deve essere in ottima forma fisica: collo, spalle e addominali lavorano per tenere la testa ferma nelle curve.\n\nAll’interno dell’abitacolo fa molto caldo: la temperatura può superare i 50 °C.` },
      { h: 'Il volante', b: `Il **volante** di una F1 è piccolo, quasi rettangolare, e somiglia più a una consolle di videogioco che a un volante normale.\n\nHa un piccolo display e decine di **pulsanti, manopole e levette**, con cui il pilota può:\n\n- cambiare le **marce** con le palette dietro il volante;\n- regolare la ripartizione della frenata e il funzionamento del differenziale;\n- gestire l’energia elettrica;\n- parlare con la squadra con il pulsante della **radio**;\n- attivare il limitatore di velocità nella corsia dei box;\n- attivare il DRS (regolamento fino al 2025).\n\nIl volante si **stacca** rapidamente, così il pilota può uscire dall’abitacolo più in fretta in emergenza.\n\nI piloti si abituano a regolare ogni funzione senza guardare, a più di 300 km/h, mantenendo la concentrazione sulla traiettoria.` },
      { h: 'Riepilogo con cifre', b: `Tabella di riferimento (ordini di grandezza, stagioni recenti):\n\n| Voce | F1 | Auto familiare |\n|---|---|---|\n| Potenza | circa 1000 CV | 100–150 CV |\n| Peso | circa 800 kg (con pilota, senza carburante) | 1300–1500 kg |\n| Peso/potenza | circa 1,25 CV/kg | circa 0,1 CV/kg |\n| Velocità massima | oltre 300 km/h | 180–200 km/h |\n| Posti | 1 | 5 |\n\nPunti da ricordare:\n\n- La F1 è molto più **potente** e molto più **leggera** di un’auto stradale.\n- L’**aerodinamica** crea carico, che permette curve veloci.\n- Il **pilota** è protetto da halo, sedile su misura, casco e cinture.\n- Il **volante** è un centro di comando.\n\nAttenzione: queste cifre dipendono dalle regole di ogni stagione. Il regolamento tecnico cambia in modo importante nel **2026** (motori e aerodinamica), quindi controlla i valori aggiornati.` }
    ],
    exercises: [
      mc('Che cos’è il carico aerodinamico (downforce)?', ['Una forza verso il basso creata dall’aria che aumenta l’aderenza', 'Il peso del carburante', 'La potenza del motore', 'La pressione delle gomme'], 0, 'Spinge l’auto contro la pista.'),
      mc('Qual è il prezzo da pagare per avere più carico?', ['Maggiore resistenza all’aria in rettilineo', 'Meno aderenza', 'Meno freni', 'Più peso del pilota'], 0, 'Più carico significa spesso meno velocità massima.'),
      fill('Una F1 ha circa 1000 CV e pesa circa 800 kg. Quanti CV per kg? (due decimali)', ['1,25', '1.25'], '1000 / 800 = 1,25.'),
      fill('Un’auto familiare ha 150 CV e pesa 1500 kg. Quanti CV per kg?', ['0,1', '0.1', '0,10', '0.10'], '150 / 1500 = 0,1.'),
      fill('Quante volte è maggiore il rapporto potenza/peso della F1 (1,25) rispetto all’auto familiare (0,1)?', ['12,5', '12.5'], '1,25 / 0,1 = 12,5.'),
      mc('Che cos’è l’halo?', ['Una struttura in titanio sopra la testa del pilota', 'Un’ala', 'Un tipo di gomma', 'Il serbatoio'], 0, 'Protegge da detriti e urti.'),
      mc('Il sedile di un pilota è:', ['Modellato sul suo corpo', 'Uguale per tutti', 'Una poltrona regolabile da auto', 'Assente'], 0, 'È su misura, per sostenere il pilota nelle curve.'),
      mc('Che cosa regola il pilota con le palette dietro il volante?', ['Il cambio marcia', 'Il colore delle gomme', 'La radio', 'Il serbatoio'], 0, 'Le palette azionano il cambio.'),
      mc('Che cosa è la monoscocca?', ['Il guscio in fibra di carbonio dove sta il pilota', 'Il motore', 'La gomma', 'L’ala'], 0, 'È la cellula di sopravvivenza.'),
      mc('Quale colore ha la gomma morbida (convenzione recente)?', ['Rosso', 'Giallo', 'Bianco', 'Verde'], 0, 'Rosso morbida, giallo media, bianco dura.'),
      order('Ordina le gomme dalla più morbida alla più dura', ['Morbida (rossa)', 'Media (gialla)', 'Dura (bianca)'], 'Più morbida = più grip ma più degrado.')
    ],
    test: [
      mc('Quanti posti ha una monoposto?', ['Uno', 'Due', 'Quattro', 'Cinque'], 0, 'Mono-posto: un solo posto.'),
      fill('Una F1 pesa 800 kg. Se il pilota con casco pesasse 80 kg, quanto pesa l’auto senza pilota (in kg)?', ['720'], '800 − 80 = 720.'),
      mc('A quale scopo serve un fondo vettura sagomato?', ['Creare carico aerodinamico', 'Raffreddare il pilota', 'Spostare il carburante', 'Dare più rumore'], 0, 'Il fondo genera una parte importante del carico.'),
      mc('Perché si dice che nelle F1 i pezzi durano poco?', ['Sono progettati al limite e sostituiti spesso', 'Perché sono di plastica', 'Perché non sono mai testati', 'Perché le gare sono lunghissime'], 0, 'Meno peso e più prestazione vogliono dire meno durata.'),
      mc('Che cosa fa il dispositivo HANS?', ['Protegge il collo del pilota negli urti', 'Regola il cambio', 'Misura la temperatura gomme', 'Aumenta la potenza'], 0, 'È un sistema di sicurezza per testa e collo.'),
      mc('Perché la F1 non ha l’aria condizionata né il bagagliaio?', ['Perché ciò che non serve alla velocità è tolto', 'Perché sono vietati', 'Perché costano troppo', 'Perché non esiste pilota'], 0, 'Peso e semplicità: la F1 è fatta per correre.'),
      mc('Quale grandezza descrive meglio la capacità di accelerare di un’auto?', ['Il rapporto potenza/peso', 'Il colore', 'La lunghezza', 'Il numero di ruote'], 0, 'Più potenza e meno peso significa più accelerazione.')
    ]
  });

  /* ---------- 8 · Guardare e capire una gara ---------- */
  C.addTopic({
    id: 'f1-guardare-una-gara', subject: 'f1', stage: 'L0', minutes: 12,
    title: 'Come guardare e capire una gara',
    summary: 'La schermata dei tempi, gap e intervalli, soste, gomme, radio e colori dei settori: a leggere una gara in tv senza perdersi.',
    objectives: ['Leggere la torre dei tempi', 'Distinguere gap e intervallo', 'Interpretare colori dei settori, gomme, soste e radio'],
    prereq: ['f1-la-monoposto-in-sintesi'],
    pages: [
      { h: 'La schermata dei tempi', b: `Durante la trasmissione, sul lato dello schermo compare la **torre dei tempi** (*timing tower*): una colonna che mostra la classifica in tempo reale.\n\nSu ogni riga trovi di solito:\n\n- la **posizione** (1, 2, 3…);\n- il **nome del pilota** abbreviato in **tre lettere** (per esempio VER, HAM, LEC);\n- il **colore** o logo della squadra;\n- il **distacco** (in secondi) dall’auto che precede o dal leader;\n- il **tipo di gomma** montata (un simbolo colorato);\n- talvolta il numero di soste effettuate.\n\nLa torre cambia in continuazione: guardare la posizione non basta, bisogna leggere i **distacchi**, che dicono chi sta guadagnando e chi sta perdendo terreno.\n\nSe la tv usa grafici diversi, il principio è lo stesso: capire chi è davanti, di quanto, e con quali gomme.` },
      { h: 'Gap e intervallo', b: `Due parole che sembrano uguali ma non lo sono.\n\n- **Gap**: il distacco dal **leader** della gara.\n- **Intervallo** (*interval*): il distacco dall’auto **immediatamente davanti**.\n\n> Esempio: il pilota A è primo; B è a 2,5 s da A; C è a 1,0 s da B.\n> - Intervallo di B = **2,5 s**; gap di B = **2,5 s**.\n> - Intervallo di C = **1,0 s**; gap di C = 2,5 + 1,0 = **3,5 s**.\n\nL’intervallo è quello che interessa per capire se ci sarà un **sorpasso** o un **attacco**: sotto **1 secondo** l’auto che insegue può usare il DRS (regolamento fino al 2025).\n\nIl gap serve a capire quanto il leader è tranquillo: se il gap del secondo scende da 8 s a 5 s in qualche giro, il secondo sta rimontando.\n\nRicorda: un valore di +3,5 vuol dire «3,5 secondi di ritardo», non punti.` },
      { h: 'I colori dei settori', b: `Mentre un pilota compie un giro, sullo schermo i tempi dei **settori** compaiono con tre colori.\n\n- **Viola**: il **miglior tempo di tutti** in quel settore (in quella sessione).\n- **Verde**: il **miglior tempo personale** del pilota in quel settore, ma non il migliore in assoluto.\n- **Giallo**: tempo **peggiore** del suo miglior tempo.\n\n> Esempio: un pilota passa il primo settore con un tempo viola (il più veloce di tutti), il secondo con un verde (suo migliore) e il terzo con un giallo (più lento del suo migliore). Il giro sarà buono ma non il suo record.\n\nI colori sono utili soprattutto in **qualifica**, perché dicono subito se un giro è competitivo. Un pilota con tre settori viola sta realizzando il **giro perfetto**.\n\nNon confondere il giallo dei settori con la bandiera gialla: sono cose diverse.` },
      { h: 'Le gomme sullo schermo', b: `Accanto al pilota in classifica compare un simbolo dei **pneumatici** montati, di solito una lettera in un cerchio colorato:\n\n- **S** (rosso): morbida *soft*;\n- **M** (giallo): media *medium*;\n- **H** (bianco): dura *hard*;\n- **I** (verde): intermedia per pioggia leggera;\n- **W** (blu): da bagnato.\n\nSpesso c’è anche l’**età** della gomma in giri (per esempio «12»).\n\nCome usarlo:\n\n- una morbida nuova parte più veloce ma dura meno;\n- una gomma con molti giri è più vecchia e probabilmente lenta (**degrado**);\n- se un pilota monta gomme diverse da chi lo precede, può essere più veloce o più lento nei giri successivi.\n\nIn gara asciutta il regolamento impone di usare **almeno due tipi di mescole asciutte** diverse (salvo gare bagnate).` },
      { h: 'Soste e strategia visibili', b: `Una **sosta ai box** (*pit stop*) serve a cambiare gomme (e a volte riparare qualcosa). Sulla torre dei tempi puoi vedere il simbolo **PIT** quando un pilota è in corsia box.\n\nQuanto costa una sosta? L’auto resta ferma circa 2–3 secondi, ma l’intero passaggio nella corsia dei box, a velocità limitata, fa perdere circa **20 secondi** rispetto a chi resta in pista (ordine di grandezza, varia da circuito a circuito).\n\n> Esempio: un pilota ha 25 s di vantaggio su un altro. Se fa una sosta da 20 s perde il vantaggio e si ritrova a 5 s di distacco… ma con gomme nuove.\n\nCosa osservare:\n\n- chi si ferma prima o dopo;\n- con quali gomme esce;\n- se rientra in pista **in traffico** (dietro altre auto) o in aria libera;\n- se cambia la strategia: una o due soste.\n\nLa strategia è decisa da cosa conviene di più in termini di tempo totale.` },
      { h: 'La radio dei team', b: `I piloti comunicano con l’**ingegnere di pista** tramite la **radio** (*team radio*). La televisione ne trasmette alcuni messaggi selezionati.\n\nTipici messaggi:\n\n- **«Box, box»**: «rientra ai box in questo giro».\n- **«Push»**: «spingi, vai più forte».\n- **«Lift and coast»** o **«gestisci»**: alza il piede prima della frenata per risparmiare carburante o gomme.\n- **«Gap» o «Delta»**: informazioni sul distacco o sul tempo.\n- **«Plan B»**: cambia strategia.\n\nCi sono regole sulle comunicazioni: la FIA vieta di dare al pilota certe informazioni per limitare gli aiuti; il regolamento viene aggiornato spesso.\n\nI messaggi sono utili per intuire le strategie: se il pilota dice «ho le gomme finite», è probabile che sia prossimo a una sosta.` },
      { h: 'Messaggi della direzione gara e penalità', b: `La **direzione gara** (*race control*) comunica con messaggi scritti, trasmessi sullo schermo e ai team. Esempi:\n\n- «**Yellow flag in sector 2**»: bandiera gialla nel settore 2;\n- «**Safety car deployed**»: la safety car è in pista;\n- «**Track limits**»: un pilota ha superato i limiti pista;\n- «**Incident under investigation**»: i commissari stanno valutando un fatto;\n- «**5 seconds time penalty**»: penalità di 5 secondi aggiunta al tempo finale.\n\nLe **penalità** più comuni:\n\n- **Penalità di tempo (5 o 10 secondi)**: viene aggiunta al tempo finale oppure scontata ai box;\n- **Drive-through**: attraversare la corsia dei box a velocità limitata, senza fermarsi;\n- **Penalità in griglia**: arretrare di alcune posizioni nella gara successiva.\n\nQuindi, la classifica «virtuale» sullo schermo può non coincidere con quella finale: le penalità possono cambiare l’ordine alla fine.` },
      { h: 'Un esempio di lettura', b: `Immagina questa torre (valori inventati):\n\n| Pos | Pilota | Gomma | Gap | Intervallo |\n|---|---|---|---|---|\n| 1 | AAA | H (12 giri) | — | — |\n| 2 | BBB | M (3 giri) | +6,8 | +6,8 |\n| 3 | CCC | M (3 giri) | +7,5 | +0,7 |\n\nCosa possiamo dedurre?\n\n- AAA è in testa con gomme dure vecchie di 12 giri; BBB e CCC hanno gomme medie nuove (3 giri): hanno fatto una sosta da poco.\n- BBB è a 6,8 s da AAA; CCC è a 0,7 s da BBB (intervallo) e a 7,5 s dal leader: 6,8 + 0,7 = 7,5.\n- CCC è sotto 1 s da BBB: può usare il DRS.\n- Le gomme nuove di BBB e CCC sono più veloci: potrebbero raggiungere AAA, se AAA non reagisce.\n\nQuindi AAA dovrà probabilmente fermarsi presto per non farsi raggiungere, oppure resistere con le gomme che ha.` }
    ],
    exercises: [
      mc('Che cos’è il gap?', ['Il distacco dal leader', 'Il distacco dall’auto davanti', 'Il numero di giri', 'La temperatura dell’asfalto'], 0, 'L’intervallo è invece il distacco dall’auto immediatamente davanti.'),
      mc('Che cos’è l’intervallo?', ['Il distacco dall’auto che precede', 'Il tempo di sosta', 'Il giro veloce', 'La lunghezza della gara'], 0, 'Il valore tra due auto consecutive.'),
      fill('B è a 2,5 s da A (primo). C è a 1,0 s da B. Quale è il gap di C dal leader, in secondi?', ['3,5', '3.5'], '2,5 + 1,0 = 3,5.'),
      fill('Il pilota D ha 25 s di vantaggio su E e fa una sosta che costa 20 s. Quanto vantaggio gli resta, in secondi?', ['5'], '25 − 20 = 5.'),
      mc('Che cosa significa un tempo di settore viola?', ['Il miglior tempo di tutti in quel settore', 'Il peggior tempo', 'Un errore del pilota', 'Una penalità'], 0, 'Viola = migliore assoluto.'),
      mc('Che cosa significa un tempo di settore verde?', ['Il miglior tempo personale del pilota', 'Il miglior tempo assoluto', 'Il peggiore', 'Una sosta'], 0, 'Verde = migliorato rispetto al proprio precedente miglior tempo.'),
      mc('Una lettera H in un cerchio bianco accanto al pilota indica:', ['Gomma dura', 'Gomma morbida', 'Pioggia estrema', 'Pilota ritirato'], 0, 'H = hard, bianca.'),
      mc('Che cosa significa «Box, box» alla radio?', ['Rientra ai box in questo giro', 'Rallenta', 'Sorpassa', 'Fine della gara'], 0, 'Chiama il pilota in sosta.'),
      mc('Quanto costa in media una sosta ai box in tempo di gara (ordine di grandezza)?', ['Circa 20 secondi', 'Circa 2 minuti', 'Circa 1 secondo', 'Circa 10 minuti'], 0, 'Il passaggio nella corsia box costa circa 20 s.'),
      mc('Una penalità di 5 secondi significa:', ['5 secondi aggiunti al tempo finale', '5 posizioni in meno', '5 punti persi', 'Squalifica'], 0, 'Si aggiungono al tempo del pilota alla fine.'),
      order('Ordina un giro di lettura della torre dei tempi', ['Guardo la posizione', 'Leggo il gap e l’intervallo', 'Controllo le gomme', 'Vedo i colori dei settori'], 'Posizione, distacchi, gomme e settori.')
    ],
    test: [
      fill('In una torre dei tempi, B è a +6,8 e C è a +0,7 da B. Quanto è il gap di C dal leader?', ['7,5', '7.5'], '6,8 + 0,7 = 7,5.'),
      mc('Se l’intervallo è +0,6, che cosa può fare il pilota che insegue (regolamento fino al 2025)?', ['Usare il DRS', 'Fermarsi', 'Prendere punti', 'Chiamare la bandiera'], 0, 'Entro 1 secondo il DRS è utilizzabile nelle zone.'),
      mc('Una gomma con molti giri è:', ['Probabilmente più lenta per il degrado', 'Sempre più veloce', 'Nuova', 'Vietata'], 0, 'Il degrado la rende meno performante.'),
      mc('Cosa vuol dire PIT sulla torre dei tempi?', ['Il pilota è in corsia box', 'Il pilota è primo', 'Il pilota è squalificato', 'Il pilota ha vinto'], 0, 'Indica la sosta in corso.'),
      mc('Una penalità drive-through è:', ['Attraversare la corsia dei box senza fermarsi', 'Un giro in meno', 'Una multa', 'Una sosta di 10 secondi'], 0, 'Si passa nella corsia dei box a velocità limitata.'),
      mc('Perché la classifica sullo schermo può cambiare alla fine?', ['Per le penalità applicate dopo la gara', 'Perché i dati sono falsi', 'Per il meteo', 'Perché il traguardo si sposta'], 0, 'Le penalità di tempo sono aggiunte al risultato.'),
      mc('Quale colore dei settori indica un tempo peggiore del proprio migliore?', ['Giallo', 'Viola', 'Verde', 'Blu'], 0, 'Giallo = non migliorato.')
    ]
  });

  /* ---------- 9 · Glossario e numeri ---------- */
  C.addTopic({
    id: 'f1-glossario-e-numeri', subject: 'f1', stage: 'L0', minutes: 12,
    title: 'Glossario e numeri di riferimento',
    summary: 'Giro veloce, pole, griglia, parco chiuso, undercut, DNF, pit stop, stint, degrado: le parole chiave e i calcoli semplici di velocità media, durata e punti.',
    objectives: ['Definire i termini principali del linguaggio della F1', 'Ricordare i numeri di riferimento', 'Svolgere calcoli semplici di velocità media, durata e punti'],
    prereq: ['f1-guardare-una-gara'],
    pages: [
      { h: 'Giro veloce, pole e griglia', b: `Tre parole che senti in ogni telecronaca.\n\n- **Giro veloce** (*fastest lap*): il giro più rapido compiuto da un pilota durante la gara. Dal 2025 non dà punti.\n- **Pole position**: il primo posto in griglia, conquistato con il miglior tempo delle qualifiche.\n- **Griglia** (*grid*): lo schieramento di partenza, a due file sfalsate, in ordine di qualifica (con eventuali penalità).\n\nDalla pole il pilota parte davanti a tutti e ha il percorso libero verso la prima curva. Ma non vince per forza: dipende da partenza, strategia e ritmo.\n\n> Ricorda: la pole si ottiene **il sabato**; il giro veloce **la domenica**, in gara. Non sono la stessa cosa.\n\nMolti Gran Premi sono vinti da chi parte in prima fila, ma i casi in cui il vincitore parte da più indietro non sono rari.` },
      { h: 'Parco chiuso', b: `Il **parco chiuso** (in francese *parc fermé*) è un regime di controllo: dopo l’inizio delle qualifiche, le squadre **non possono modificare liberamente** l’auto. Servono per mantenere l’equità: se l’assetto cambiasse del tutto tra qualifica e gara, il lavoro fatto in qualifica non avrebbe valore.\n\nIn pratica:\n\n- le regolazioni principali devono restare quelle usate in qualifica;\n- sono ammesse poche modifiche, per esempio riparazioni o controlli;\n- se una squadra modifica l’auto in modo non consentito, il pilota può partire dai box (corsia dei box) invece che dalla griglia.\n\nIl termine indica anche il **luogo** dove, dopo la gara, le auto dei primi vengono portate per i controlli dei tecnici FIA (peso, parti e conformità).\n\nLe regole di dettaglio (che cosa si può cambiare) sono molto tecniche e variano di stagione in stagione.` },
      { h: 'Pit stop, stint e sosta', b: `Il **pit stop** (sosta ai box) è la fermata per cambiare gomme (e a volte riparare qualcosa). Lo **stint** è il tratto di gara fra due soste: il blocco di giri percorso con lo stesso set di gomme.\n\n> Esempio: gara di 60 giri con una sola sosta al giro 24.\n> - Primo stint: **24 giri**.\n> - Secondo stint: 60 − 24 = **36 giri**.\n\nCon due soste ci sono **tre stint**.\n\nQuanti pit stop? Dipende da gomme, pista, meteo, safety car. In gara asciutta si deve usare almeno due mescole diverse, quindi in genere serve **almeno una sosta**.\n\nIl **pit window** è l’intervallo di giri in cui la sosta conviene. La **pit lane** è la corsia dei box e ha un **limite di velocità** (spesso 80 km/h, in alcune piste 60).\n\nChi sceglie male quando fermarsi può perdere posizioni anche se è veloce.` },
      { h: 'Undercut e overcut', b: `Sono due **tattiche** di sosta per superare un avversario senza sorpassarlo in pista.\n\n- **Undercut**: ti fermi **prima** dell’avversario. Con gomme nuove fai giri veloci; quando lui si ferma, esce dietro (o davanti, se i tuoi giri veloci hanno compensato la perdita).\n- **Overcut**: ti fermi **dopo**. Resti in pista con gomme usate ma ancora in buone condizioni e con poco traffico; quando ti fermi, esci davanti.\n\n> Esempio semplificato. A è davanti a B di 2 s. B si ferma per primo e, con gomme nuove, gira 1,5 s più veloce di A (che ha ancora le gomme vecchie) per 2 giri: guadagna 1,5 × 2 = 3 s. Quando A si ferma a sua volta, la sosta costa a entrambi lo stesso tempo, ma B ha recuperato 3 s contro i 2 s di distacco: esce davanti.\n\nL’undercut funziona soprattutto quando le gomme **degradano** molto. Non è una garanzia: se, uscendo dai box, il pilota trova traffico lento, perde il vantaggio.` },
      { h: 'Degrado', b: `Il **degrado** (*degradation*, spesso abbreviato in «deg») è la **perdita di prestazione** delle gomme col passare dei giri. Una gomma nuova fa un giro più veloce di una vecchia di molti giri.\n\nOrdine di grandezza: una gomma può perdere una frazione di secondo al giro, per esempio **0,05–0,1 s per giro**, ma il valore cambia molto da pista a pista, da mescola a mescola e da come guida il pilota.\n\n> Esempio: degrado di 0,08 s/giro per 20 giri → 0,08 × 20 = **1,6 s** di differenza tra il primo e il ventesimo giro.\n\nCi sono due fenomeni vicini:\n\n- **degrado termico**: gomme troppo calde;\n- **usura**: il battistrada si consuma.\n\nIl pilota deve gestire la gomma (guidare «dolce») per non consumarla troppo. Quando il degrado diventa improvviso e le prestazioni crollano, si parla di «**cliff**» (precipizio).` },
      { h: 'DNF, DNS, DSQ e le altre sigle', b: `Nelle classifiche trovi sigle brevi, spesso in inglese.\n\n- **DNF** (*Did Not Finish*): non ha finito la gara (ritiro).\n- **DNS** (*Did Not Start*): non ha preso il via.\n- **DSQ**: squalificato.\n- **NC** (*Not Classified*): non classificato, perché ha percorso meno del 90% della distanza del vincitore.\n- **PIT**: in corsia box.\n- **+1 LAP**: doppiato, un giro in meno del vincitore.\n- **FP1, FP2, FP3**: prove libere.\n- **Q1, Q2, Q3**: parti delle qualifiche.\n- **SC / VSC**: safety car / virtual safety car.\n- **DRS**: sistema di riduzione della resistenza (regolamento fino al 2025).\n\nUn **DNF** non vuol dire necessariamente un incidente: può essere un guasto meccanico o idraulico, una foratura, un problema elettrico.\n\nChi non finisce una gara prende **zero punti** (se non è classificato), anche se aveva guidato in testa fino a poco prima.` },
      { h: 'Numeri di riferimento', b: `Tabella di numeri da ricordare (regolamento delle stagioni recenti; ordini di grandezza dove indicato).\n\n| Voce | Valore |\n|---|---|\n| Squadre / auto | 10 / 20 (11 / 22 previste dal 2026) |\n| Gran Premi per stagione | fino a 24 |\n| Prove libere | 60 minuti |\n| Qualifiche | Q1 18 min, Q2 15 min, Q3 12 min |\n| Gara: distanza minima | 305 km (Monaco circa 260 km) |\n| Gara: tempo massimo | 2 ore |\n| Sprint | circa 100 km |\n| Punti in gara | 25-18-15-12-10-8-6-4-2-1 |\n| Punti sprint | 8-7-6-5-4-3-2-1 |\n| Giro veloce | nessun punto dal 2025 |\n| Costo sosta nel tempo di gara | circa 20 s (ordine di grandezza) |\n| Power unit | circa 1000 CV |\n| Peso minimo | circa 800 kg |\n| Velocità massima | oltre 300 km/h |\n\nCambiano ogni anno: se un dato ti serve per una decisione importante, verifica sempre il regolamento dell’anno in corso.` },
      { h: 'Calcoli semplici', b: `Tre formule bastano per i calcoli di base.\n\n**Velocità media** = distanza / tempo.\n> 306 km in 1,5 ore → 306 / 1,5 = **204 km/h**.\n\n**Tempo** = distanza / velocità.\n> 300 km a 200 km/h → 300 / 200 = 1,5 h = **90 minuti**.\n\n**Distanza di gara** = lunghezza del giro × numero di giri.\n> 5 km × 60 giri = **300 km**.\n\nGiro di 5 km in 80 s: velocità media = 5 / 80 × 3600 = **225 km/h**.\n\n**Punti**: somma della scala per ogni risultato.\n> 3° in gara (15) + 5° nello sprint (4) = **19**.\n\nPer passare da km/h a m/s dividi per 3,6; per passare da m/s a km/h moltiplica per 3,6.\n\nQuesti calcoli sono la base per tutto ciò che seguirà nel corso: strategie, tempi e confronti si fanno con le stesse formule.` }
    ],
    exercises: [
      mc('Che cos’è la pole position?', ['Il primo posto in griglia, conquistato in qualifica', 'Il giro più veloce in gara', 'La bandiera a scacchi', 'Il primo pit stop'], 0, 'Va al miglior tempo delle qualifiche.'),
      mc('Che cos’è il parco chiuso?', ['Il regime per cui l’auto non può essere modificata liberamente dopo l’inizio delle qualifiche', 'Un parcheggio per i tifosi', 'La corsia dei box', 'Un tipo di gomma'], 0, 'Evita grandi cambi di assetto tra qualifica e gara.'),
      mc('Che cosa significa DNF?', ['Non ha finito la gara', 'Non è partito', 'Squalificato', 'Doppiato'], 0, 'Did Not Finish.'),
      mc('Che cos’è lo stint?', ['Il tratto di gara tra due soste', 'Un tipo di gomma', 'Un settore', 'Un cordolo'], 0, 'Un blocco di giri con lo stesso set di gomme.'),
      fill('Gara di 60 giri con una sola sosta al giro 24. Quanti giri dura il secondo stint?', ['36'], '60 − 24 = 36.'),
      fill('Distanza 306 km percorsa in 1,5 ore. Velocità media in km/h?', ['204'], '306 / 1,5 = 204.'),
      fill('Quanti minuti servono per 300 km a 200 km/h?', ['90'], '300 / 200 = 1,5 h = 90 minuti.'),
      fill('Giro di 5 km percorso in 80 secondi. Velocità media in km/h?', ['225'], '5 / 80 × 3600 = 225.'),
      fill('Degrado di 0,08 s al giro per 20 giri: quanti secondi in totale? (un decimale)', ['1,6', '1.6'], '0,08 × 20 = 1,6.'),
      mc('Che cosa è un undercut?', ['Fermarsi prima dell’avversario per sfruttare gomme nuove', 'Fermarsi dopo l’avversario', 'Un sorpasso in curva', 'Una penalità'], 0, 'L’undercut punta sul vantaggio delle gomme fresche.'),
      order('Ordina i passaggi per calcolare la velocità media di un giro', ['Lunghezza del giro in km', 'Tempo del giro in secondi', 'Dividi la lunghezza per il tempo', 'Moltiplica per 3600'], 'v = km / s × 3600 = km/h.')
    ],
    test: [
      fill('Un pilota percorre 4 km in 60 secondi. Velocità media in km/h?', ['240'], '4 / 60 × 3600 = 240.'),
      fill('Una gara di 280 km a 200 km/h media. Quanti minuti dura?', ['84'], '280 / 200 = 1,4 h = 84 minuti.'),
      fill('Un pilota arriva 4° in gara e 2° nello sprint. Quanti punti nel weekend?', ['19'], '12 + 7 = 19.'),
      fill('Una squadra ha piloti al 1° e al 3° posto. Quanti punti prende in gara?', ['40'], '25 + 15 = 40.'),
      mc('Che differenza c’è tra pole e giro veloce?', ['La pole si ottiene in qualifica, il giro veloce in gara', 'Sono la stessa cosa', 'La pole è in gara, il giro veloce in qualifica', 'Nessuna delle due esiste più'], 0, 'Due momenti e due significati diversi.'),
      mc('Perché un DNF non significa sempre un incidente?', ['Può essere un guasto meccanico o altro problema', 'Perché non esiste', 'Perché indica una vittoria', 'Perché è un premio'], 0, 'Il ritiro può avere molte cause.'),
      mc('Una gara dura 54 giri e fa due soste (ai giri 18 e 36). Quanti giri ha il secondo stint?', ['18', '36', '54', '12'], 0, 'Tra il giro 18 e il giro 36 ci sono 18 giri.'),
      mc('Quanti stint ci sono se si fanno due soste?', ['3', '2', '4', '1'], 0, 'Due soste dividono la gara in tre tratti.')
    ]
  });
})(window.ST = window.ST || {});
